'use client'

import { useEffect, useState } from 'react'
import { useRouter, useParams, useSearchParams } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api, Collection } from '@/lib/api'
import { useEditorStore, TreeItem } from '@/lib/editor-store'
import DashboardLayout from '@/components/DashboardLayout'
import SourceCollectionPanel from '@/components/SourceCollectionPanel'
import ConfirmDialog from '@/components/ConfirmDialog'
import AlertDialog from '@/components/AlertDialog'
import {
  DndContext,
  DragOverlay,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragStartEvent,
  DragEndEvent,
  DragOverEvent,
  useDroppable,
} from '@dnd-kit/core'
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'

interface SortableItemProps {
  item: TreeItem
  depth: number
  isExpanded: boolean
  isSelected: boolean
  isDropTarget: boolean
  isActiveFolder: boolean
  onToggleFolder: () => void
  onToggleSelect: () => void
  onRename: (newTitle: string) => void
  onUpdateUrl?: (newUrl: string) => void
  onDelete: () => void
}

function SortableItem({
  item,
  depth,
  isExpanded,
  isSelected,
  isDropTarget,
  isActiveFolder,
  onToggleFolder,
  onToggleSelect,
  onRename,
  onUpdateUrl,
  onDelete
}: SortableItemProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editTitle, setEditTitle] = useState(item.title)
  const [isEditingUrl, setIsEditingUrl] = useState(false)
  const [editUrl, setEditUrl] = useState(item.url || '')

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: item.masterId })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.4 : 1,
    zIndex: isDragging ? 50 : 1,
  }

  const handleSaveTitle = () => {
    if (editTitle.trim() && editTitle !== item.title) {
      onRename(editTitle.trim())
    }
    setIsEditing(false)
  }

  const handleSaveUrl = () => {
    if (editUrl.trim() && editUrl !== item.url && onUpdateUrl) {
      onUpdateUrl(editUrl.trim())
    }
    setIsEditingUrl(false)
  }

  return (
    <div ref={setNodeRef} style={style} className="group/item mb-1">
      <div
        className={`flex items-center gap-3 px-4 py-3 rounded-2xl transition-all border ${
          isDropTarget
            ? 'bg-emerald-50/80 dark:bg-emerald-500/10 border-emerald-400 dark:border-emerald-500/40 ring-2 ring-emerald-400/50 dark:ring-emerald-500/30 shadow-lg shadow-emerald-500/10'
            : isActiveFolder
              ? 'bg-amber-50/80 dark:bg-amber-500/10 border-amber-400 dark:border-amber-500/40 shadow-sm'
              : isSelected
                ? 'bg-primary-50/50 dark:bg-terra-500/10 border-primary-200 dark:border-terra-500/20 shadow-sm'
                : 'hover:bg-slate-50 dark:hover:bg-white/5 border-transparent hover:border-slate-100 dark:hover:border-white/5'
          } ${isDragging ? 'shadow-2xl brightness-95' : ''}`}
        style={{ paddingLeft: `${depth * 28 + 16}px` }}
      >
        {/* Drag Handle */}
        <button
          {...attributes}
          {...listeners}
          className="cursor-grab active:cursor-grabbing text-slate-300 dark:text-white/30 hover:text-slate-600 dark:hover:text-cream-500 transition-colors p-1"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8h16M4 16h16" />
          </svg>
        </button>

        {/* Checkbox */}
        <div className="relative flex items-center">
          <input
            type="checkbox"
            checked={isSelected}
            onChange={onToggleSelect}
            className="peer h-5 w-5 cursor-pointer appearance-none rounded-lg border-2 border-slate-200 dark:border-white/[0.06] bg-white dark:bg-[#242424] transition-all checked:border-primary-600 dark:checked:border-terra-500 checked:bg-primary-600 dark:checked:bg-terra-500 focus:outline-none focus:ring-4 focus:ring-primary-500/10 dark:focus:ring-terra-500/20"
          />
          <svg className="pointer-events-none absolute left-1/2 top-1/2 h-3 w-3 -translate-x-1/2 -translate-y-1/2 text-white opacity-0 peer-checked:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" />
          </svg>
        </div>

        {/* Folder toggle or spacer */}
        {item.type === 'folder' ? (
          <button
            onClick={onToggleFolder}
            className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${isExpanded ? 'bg-primary-50 dark:bg-terra-500/10 text-primary-600 dark:text-terra-400' : 'text-slate-400 dark:text-white/40 hover:text-slate-600 dark:hover:text-cream-500'}`}
          >
            <svg
              className={`w-3.5 h-3.5 transition-transform duration-300 ${isExpanded ? 'rotate-90' : ''}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
            </svg>
          </button>
        ) : (
          <div className="w-6"></div>
        )}

        {/* Content Icon */}
        <div className="w-8 h-8 rounded-xl bg-white dark:bg-[#242424] border border-slate-100 dark:border-white/5 flex items-center justify-center text-lg shadow-sm shrink-0">
          {item.type === 'folder' ? '📁' : item.favicon ? (
            <img src={item.favicon} alt="" className="w-4 h-4 object-contain" />
          ) : '🔖'}
        </div>

        {/* Title Logic */}
        <div className="flex-1 min-w-0">
          {isEditing ? (
            <input
              type="text"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              onBlur={handleSaveTitle}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSaveTitle()
                if (e.key === 'Escape') {
                  setEditTitle(item.title)
                  setIsEditing(false)
                }
              }}
              className="w-full px-3 py-1 bg-white dark:bg-[#242424] border-2 border-primary-500 dark:border-terra-500 rounded-lg focus:outline-none font-bold text-slate-900 dark:text-cream-100"
              autoFocus
            />
          ) : (
            <div className="flex flex-col">
              <span
                className="font-bold text-slate-700 dark:text-white/70 truncate cursor-text"
                onDoubleClick={() => setIsEditing(true)}
              >
                {item.title}
              </span>
              {item.type === 'bookmark' && item.url && !isEditingUrl && (
                <span
                  className="text-[10px] font-medium text-slate-400 dark:text-white/40 truncate max-w-[300px] cursor-text"
                  onDoubleClick={() => setIsEditingUrl(true)}
                >
                  {item.url.replace(/^https?:\/\/(www\.)?/, '')}
                </span>
              )}
            </div>
          )}
        </div>

        {isEditingUrl && (
          <input
            type="text"
            value={editUrl}
            onChange={(e) => setEditUrl(e.target.value)}
            onBlur={handleSaveUrl}
            onKeyDown={(e) => {
              if (e.key === 'Enter') handleSaveUrl()
              if (e.key === 'Escape') {
                setEditUrl(item.url || '')
                setIsEditingUrl(false)
              }
            }}
            className="w-64 px-3 py-1 text-xs bg-white dark:bg-[#242424] border-2 border-primary-500 dark:border-terra-500 rounded-lg focus:outline-none font-medium text-slate-900 dark:text-cream-100"
            autoFocus
          />
        )}

        {/* Stats for folders */}
        {item.type === 'folder' && (
          <span className="text-[10px] font-black text-slate-300 dark:text-white/30 uppercase tracking-widest hidden sm:block">
            {item.children?.length || 0} items
          </span>
        )}

        {/* Action Buttons */}
        <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-all ml-4">
          {item.type === 'bookmark' && item.url && (
            <a
              href={item.url}
              target="_blank"
              rel="noopener noreferrer"
              className="w-8 h-8 flex items-center justify-center text-slate-400 dark:text-white/40 hover:text-primary-600 dark:hover:text-terra-400 hover:bg-white dark:hover:bg-[#242424] rounded-lg transition-all border border-transparent hover:border-slate-100 dark:hover:border-white/5 hover:shadow-sm"
              title="Open link"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
            </a>
          )}
          <button
            onClick={onDelete}
            className="w-8 h-8 flex items-center justify-center text-slate-400 dark:text-white/40 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-all border border-transparent hover:border-red-100 dark:hover:border-red-500/20"
            title="Delete"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  )
}

function DroppableFolder({ masterId, children }: { masterId: string; children: React.ReactNode }) {
  const { setNodeRef, isOver } = useDroppable({
    id: `drop-${masterId}`,
    data: { targetFolderId: masterId },
  })

  return (
    <div
      ref={setNodeRef}
      className={`transition-all rounded-2xl ${
        isOver
          ? 'ring-2 ring-primary-500 dark:ring-terra-500 bg-primary-50/50 dark:bg-terra-500/10'
          : ''
      }`}
    >
      {children}
    </div>
  )
}

export default function CollectionEditorPage() {
  const router = useRouter()
  const params = useParams()
  const searchParams = useSearchParams()
  const collectionId = params.id as string
  const { user, token, isLoading, isPremium } = useAuth()
  const [collection, setCollection] = useState<Collection | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [showAddModal, setShowAddModal] = useState<'folder' | 'bookmark' | null>(null)
  const [newItemTitle, setNewItemTitle] = useState('')
  const [newItemUrl, setNewItemUrl] = useState('')
  const [activeId, setActiveId] = useState<string | null>(null)
  const [activeDragData, setActiveDragData] = useState<{ title: string; type: string; isSource: boolean; count: number } | null>(null)
  const [importNotice, setImportNotice] = useState<string | null>(null)
  const [dropTargetId, setDropTargetId] = useState<string | null>(null)
  const [sourceCollectionIdRef, setSourceCollectionIdRef] = useState<string>('')
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null)
  const [deleteConfirm, setDeleteConfirm] = useState<{ isOpen: boolean; title: string; masterIds: string[] }>({ isOpen: false, title: '', masterIds: [] })
  const [saveErrorDialog, setSaveErrorDialog] = useState<{ isOpen: boolean; message: string }>({ isOpen: false, message: '' })

  const showImportPanel = searchParams.get('import') === 'true'

  const toggleImportPanel = () => {
    const editPath = `/collections/${collectionId}/edit`
    if (showImportPanel) {
      router.replace(editPath)
    } else {
      router.replace(`${editPath}?import=true`)
    }
  }

  const {
    tree,
    expandedFolders,
    selectedItems,
    hasUnsavedChanges,
    pendingChanges,
    loadData,
    toggleFolder,
    toggleSelect,
    clearSelection,
    renameItem,
    updateBookmarkUrl,
    deleteItem,
    addFolder,
    addBookmark,
    moveItem,
    importSourceItems,
    clearChanges,
    revertChanges
  } = useEditorStore()

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  )

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
    if (!isLoading && user && !isPremium) {
      router.push(`/collections/${collectionId}`)
    }
  }, [isLoading, user, isPremium, router, collectionId])

  useEffect(() => {
    if (token && collectionId && isPremium) {
      loadCollection()
    }
  }, [token, collectionId, isPremium])

  async function loadCollection() {
    if (!token) return
    try {
      // Handle "default" alias - resolve to actual default collection ID
      let actualCollectionId = collectionId
      if (collectionId === 'default') {
        const collections = await api.getCollections(token)
        const defaultCollection = collections.collections.find(c => c.isDefault === 1)
        if (defaultCollection) {
          actualCollectionId = defaultCollection.id
          // Update URL to actual ID without reloading
          router.replace(`/collections/${actualCollectionId}/edit`, undefined)
        }
      }

      const data = await api.getCollection(token, actualCollectionId)
      setCollection(data.collection)
      loadData(data.folders, data.bookmarks)
    } catch (error) {
      console.error('Failed to load collection:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async () => {
    if (!token || pendingChanges.length === 0) return

    setSaving(true)
    try {
      await api.applyChanges(token, collectionId, pendingChanges)
      clearChanges()
      // Reload to get updated data
      await loadCollection()
    } catch (error) {
      console.error('Failed to save changes:', error)
      setSaveErrorDialog({ isOpen: true, message: 'Failed to save changes. Please try again.' })
    } finally {
      setSaving(false)
    }
  }

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault()
    if (!newItemTitle.trim()) return

    if (showAddModal === 'folder') {
      addFolder(activeFolderId, newItemTitle.trim())
    } else if (showAddModal === 'bookmark' && newItemUrl.trim()) {
      addBookmark(activeFolderId, newItemTitle.trim(), newItemUrl.trim())
    }

    setShowAddModal(null)
    setNewItemTitle('')
    setNewItemUrl('')
  }

  const handleBulkDelete = () => {
    if (selectedItems.size === 0) return
    setDeleteConfirm({
      isOpen: true,
      title: `Delete ${selectedItems.size} selected item${selectedItems.size === 1 ? '' : 's'}?`,
      masterIds: Array.from(selectedItems)
    })
  }

  const executeDelete = () => {
    deleteConfirm.masterIds.forEach(masterId => {
      const item = findItemByMasterId(tree, masterId)
      if (item) {
        deleteItem(masterId, item.type)
      }
    })
    clearSelection()
    setDeleteConfirm({ isOpen: false, title: '', masterIds: [] })
  }

  const findItemByMasterId = (items: TreeItem[], masterId: string): TreeItem | null => {
    for (const item of items) {
      if (item.masterId === masterId) return item
      if (item.children) {
        const found = findItemByMasterId(item.children, masterId)
        if (found) return found
      }
    }
    return null
  }

  const handleDragStart = (event: DragStartEvent) => {
    const id = event.active.id as string
    setActiveId(id)
    setDropTargetId(null)

    const data = event.active.data?.current
    if (data?.sourceItem) {
      const count = data.selectedItems?.length || 1
      setActiveDragData({ title: data.title || 'item', type: data.type || 'bookmark', isSource: true, count })
    } else {
      const item = findItemByMasterId(tree, id)
      if (item) {
        setActiveDragData({ title: item.title, type: item.type, isSource: false, count: 1 })
      }
    }
  }

  const handleDragOver = (event: DragOverEvent) => {
    const { active, over } = event
    const isSourceDrag = (active.id as string).startsWith('source-') || active.data?.current?.sourceItem

    if (over && typeof over.id === 'string') {
      if (over.id.startsWith('drop-')) {
        setDropTargetId(over.data?.current?.targetFolderId || null)
        return
      }
      // For both source drags and internal drags, highlight when hovering over a folder
      const overItem = findItemByMasterId(tree, over.id)
      if (overItem && overItem.type === 'folder') {
        setDropTargetId(overItem.masterId)
        return
      }
    }
    setDropTargetId(null)
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event
    setActiveId(null)
    setActiveDragData(null)
    setDropTargetId(null)

    if (!over) return

    const activeIdStr = active.id as string
    const isSourceItem = activeIdStr.startsWith('source-') || active.data?.current?.sourceItem

    if (isSourceItem) {
      // Cross-panel import: source → destination (staged as pending change)
      const sourceData = active.data?.current
      if (!sourceData) return

      const srcCollectionId = sourceData.sourceCollectionId || sourceCollectionIdRef
      if (!srcCollectionId) return

      const overId = over.id as string
      let targetParentId: string | null = null

      if (overId.startsWith('drop-')) {
        targetParentId = over.data?.current?.targetFolderId || null
      } else {
        const overItem = findItemByMasterId(tree, overId)
        if (overItem && overItem.type === 'folder') {
          targetParentId = overItem.masterId
        }
      }

      const itemsToImport = sourceData.selectedItems && sourceData.selectedItems.length > 0
        ? sourceData.selectedItems
        : [{ masterId: sourceData.masterId, type: sourceData.type, title: sourceData.title, url: sourceData.url }]

      importSourceItems(itemsToImport, targetParentId, srcCollectionId)

      const count = itemsToImport.length
      setImportNotice(`Staged ${count} item${count !== 1 ? 's' : ''} for import — click Commit to save`)
      setTimeout(() => setImportNotice(null), 4000)
      return
    }

    // Internal drag and drop
    if (active.id === over.id) return

    const activeItem = findItemByMasterId(tree, active.id as string)
    if (!activeItem) return

    const overId = over.id as string
    const overItem = findItemByMasterId(tree, overId)

    // Check if dropping onto a folder
    if (overItem && overItem.type === 'folder' && overItem.masterId !== activeItem.masterId) {
      // Move item into the folder (append to end)
      // Find the folder's current children count to determine position
      const targetFolder = findItemByMasterId(tree, overItem.masterId)
      const newPosition = targetFolder?.children?.length || 0
      moveItem(active.id as string, activeItem.type, overItem.masterId, newPosition)
      return
    }

    // Otherwise, handle root-level reordering
    const oldIndex = tree.findIndex(item => item.masterId === active.id)
    const newIndex = tree.findIndex(item => item.masterId === over.id)

    if (oldIndex !== -1 && newIndex !== -1) {
      moveItem(active.id as string, activeItem.type, null, newIndex)
    }
  }

  const renderItem = (item: TreeItem, depth: number = 0): React.ReactNode => {
    const isExpanded = expandedFolders.has(item.masterId)
    const isSelected = selectedItems.has(item.masterId)
    const isActiveFolder = activeFolderId === item.masterId

    const itemContent = (
      <div key={item.masterId}>
        <SortableItem
          item={item}
          depth={depth}
          isExpanded={isExpanded}
          isSelected={isSelected}
          isDropTarget={item.type === 'folder' && dropTargetId === item.masterId}
          isActiveFolder={isActiveFolder}
          onToggleFolder={() => toggleFolder(item.masterId)}
          onToggleSelect={() => {
            toggleSelect(item.masterId)
            if (item.type === 'folder') {
              setActiveFolderId(item.masterId)
            }
          }}
          onRename={(newTitle) => renameItem(item.masterId, item.type, newTitle)}
          onUpdateUrl={item.type === 'bookmark' ? (newUrl) => updateBookmarkUrl(item.masterId, newUrl) : undefined}
          onDelete={() => {
            setDeleteConfirm({
              isOpen: true,
              title: `Delete "${item.title}"${item.type === 'folder' ? ' and all its contents' : ''}?`,
              masterIds: [item.masterId]
            })
          }}
        />
        {item.type === 'folder' && isExpanded && item.children && (
          <div>
            {item.children.map(child => renderItem(child, depth + 1))}
          </div>
        )}
      </div>
    )

    // Always wrap folders in DroppableFolder for internal drag and drop
    if (item.type === 'folder') {
      return (
        <DroppableFolder key={item.masterId} masterId={item.masterId}>
          {itemContent}
        </DroppableFolder>
      )
    }

    return itemContent
  }

  if (isLoading || !user || !isPremium) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  const activeItem = activeId ? findItemByMasterId(tree, activeId) : null
  const allItemIds = tree.map(item => item.masterId)

  return (
    <DashboardLayout>
      <div className={`mx-auto ${showImportPanel ? 'max-w-7xl' : 'max-w-4xl'} transition-all duration-300`}>
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 mb-10">
          <div className="flex items-center gap-5">
            <Link
              href={`/collections/${collectionId}`}
              className="w-12 h-12 bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] rounded-2xl flex items-center justify-center text-slate-400 dark:text-white/40 hover:text-primary-600 dark:hover:text-terra-400 hover:border-primary-100 dark:hover:border-terra-500/30 hover:shadow-lg hover:shadow-primary-500/5 transition-all group"
            >
              <svg className="w-6 h-6 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </Link>
            <div>
              <h1 className="text-3xl font-black text-slate-900 dark:text-cream-100 tracking-tight">
                {loading ? 'Entering Editor...' : `Edit: ${collection?.name}`}
              </h1>
              <p className="text-slate-500 dark:text-white/50 mt-1 font-medium flex items-center gap-2">
                {hasUnsavedChanges ? (
                  <>
                    <span className="w-2 h-2 bg-primary-500 rounded-full animate-pulse"></span>
                    <span className="text-primary-600 dark:text-terra-400 font-bold uppercase tracking-widest text-[10px]">
                      {pendingChanges.length} Unsaved Changes
                    </span>
                  </>
                ) : (
                  <span className="text-slate-400 dark:text-white/40 font-bold uppercase tracking-widest text-[10px]">
                    Environment Synced
                  </span>
                )}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {hasUnsavedChanges && (
              <button
                onClick={revertChanges}
                className="bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] hover:bg-slate-50 dark:hover:bg-white/5 text-slate-700 dark:text-white/70 px-6 py-3 rounded-xl font-bold transition-all active:scale-95"
              >
                Discard
              </button>
            )}
            <button
              onClick={handleSave}
              disabled={!hasUnsavedChanges || saving}
              className="bg-primary-600 dark:bg-terra-500 hover:bg-primary-700 dark:hover:bg-terra-600 disabled:opacity-50 disabled:bg-slate-300 dark:disabled:bg-white/20 text-white px-8 py-3 rounded-xl font-bold transition-all shadow-lg shadow-primary-500/20 active:scale-95 flex items-center gap-2"
            >
              {saving ? (
                <>
                  <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
                  Saving...
                </>
              ) : (
                <>
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 13l4 4L19 7" />
                  </svg>
                  Commit changes
                </>
              )}
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-6 p-4 bg-white dark:bg-[#242424] rounded-[2rem] border border-slate-200 dark:border-white/[0.06] shadow-sm">
          <div className="flex items-center gap-3 w-full sm:w-auto">
            <button
              onClick={() => setShowAddModal('folder')}
              className="flex-1 sm:flex-initial flex items-center justify-center gap-2 px-5 py-2.5 text-sm bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-[#242424] hover:border-slate-200 dark:hover:border-white/[0.06] hover:shadow-sm rounded-xl font-bold text-slate-700 dark:text-white/70 transition-all"
            >
              <span className="text-base">📁</span> New Folder
            </button>
            <button
              onClick={() => { setNewItemUrl('https://'); setShowAddModal('bookmark') }}
              className="flex-1 sm:flex-initial flex items-center justify-center gap-2 px-5 py-2.5 text-sm bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-[#242424] hover:border-slate-200 dark:hover:border-white/[0.06] hover:shadow-sm rounded-xl font-bold text-slate-700 dark:text-white/70 transition-all"
            >
              <span className="text-base">🔖</span> New Link
            </button>
            <div className="w-px h-8 bg-slate-200 dark:bg-white/[0.06] hidden sm:block" />
            <button
              onClick={toggleImportPanel}
              className={`flex-1 sm:flex-initial flex items-center justify-center gap-2 px-5 py-2.5 text-sm border rounded-xl font-bold transition-all ${
                showImportPanel
                  ? 'bg-primary-50 dark:bg-terra-500/10 border-primary-200 dark:border-terra-500/20 text-primary-700 dark:text-terra-400'
                  : 'bg-slate-50 dark:bg-white/5 border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-[#242424] hover:border-slate-200 dark:hover:border-white/[0.06] hover:shadow-sm text-slate-700 dark:text-white/70'
              }`}
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
              </svg>
              {showImportPanel ? 'Close Import' : 'Import from Collection'}
            </button>
          </div>
          {activeFolderId && (
            <div className="flex items-center gap-4 w-full sm:w-auto bg-amber-50 dark:bg-amber-500/10 text-amber-800 dark:text-amber-300 px-5 py-2.5 rounded-xl animate-in zoom-in-95 duration-200">
              <span className="text-xs font-black uppercase tracking-widest border-r border-amber-300 dark:border-amber-500/30 pr-4">Active Folder</span>
              <div className="flex items-center gap-3">
                <span className="text-xs font-bold truncate max-w-[150px]">{findItemByMasterId(tree, activeFolderId)?.title || 'Unknown'}</span>
                <button
                  onClick={() => setActiveFolderId(null)}
                  className="text-amber-600 dark:text-amber-400 hover:text-amber-800 dark:hover:text-amber-200 font-bold text-xs"
                  title="Clear active folder"
                >
                  ✕
                </button>
              </div>
            </div>
          )}
          {selectedItems.size > 0 && (
            <div className="flex items-center gap-4 w-full sm:w-auto bg-slate-900 text-white px-5 py-2.5 rounded-xl animate-in zoom-in-95 duration-200">
              <span className="text-xs font-black uppercase tracking-widest border-r border-white/20 pr-4">{selectedItems.size} Selected</span>
              <div className="flex items-center gap-3">
                <button
                  onClick={clearSelection}
                  className="text-white/60 hover:text-white font-bold text-xs"
                >
                  Clear
                </button>
                <button
                  onClick={handleBulkDelete}
                  className="bg-red-500 hover:bg-red-600 px-3 py-1.5 rounded-lg text-xs font-black uppercase tracking-tighter transition-colors"
                >
                  Purge Items
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Import notice toast */}
        {importNotice && (
          <div className="mb-4 px-5 py-3 rounded-2xl bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-200 dark:border-emerald-500/20 text-emerald-700 dark:text-emerald-300 text-sm font-bold flex items-center gap-3 animate-in slide-in-from-top duration-300">
            <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
            {importNotice}
          </div>
        )}

        {/* Main Content Area — wraps DndContext around both panels */}
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={handleDragStart}
          onDragOver={handleDragOver}
          onDragEnd={handleDragEnd}
        >
          <div className={`flex gap-6 mb-10 ${showImportPanel ? '' : ''}`}>
            {/* Source Panel (left) */}
            {showImportPanel && token && (
              <div className="w-[38%] shrink-0 min-h-[500px]">
                <SourceCollectionPanel
                  token={token}
                  currentCollectionId={collectionId}
                  onClose={() => router.replace(`/collections/${collectionId}/edit`)}
                  onSourceCollectionChange={(id) => setSourceCollectionIdRef(id)}
                />
              </div>
            )}

            {/* Editor Container (right or full) */}
            <div className={`${showImportPanel ? 'flex-1 min-w-0' : 'w-full'}`}>
              <div className="bg-white dark:bg-[#242424] rounded-[2.5rem] border border-slate-200 dark:border-white/[0.06] min-h-[500px] shadow-sm overflow-hidden">
                <div className="px-10 py-5 border-b border-slate-50 dark:border-white/5 bg-slate-50/30 dark:bg-white/5 flex items-center justify-between text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-white/40">
                  <span>{showImportPanel ? 'Destination Collection' : 'Structure Hierarchy'}</span>
                  <span>Management</span>
                </div>
                {loading ? (
                  <div className="p-32 text-center text-slate-400 dark:text-white/40">
                    <div className="w-10 h-10 border-4 border-slate-100 dark:border-white/5 border-t-primary-600 dark:border-t-terra-500 rounded-full animate-spin mx-auto mb-6"></div>
                    <p className="font-bold uppercase tracking-widest text-[10px]">Calibrating Editor...</p>
                  </div>
                ) : tree.length === 0 ? (
                  <div className="p-32 text-center">
                    <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
                      <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                      </svg>
                    </div>
                    <h3 className="text-2xl font-black text-slate-900 dark:text-cream-100 mb-2">Workspace Empty</h3>
                    <p className="text-slate-500 dark:text-white/50 font-medium">
                      {showImportPanel
                        ? 'Drag items from the source panel on the left into this collection.'
                        : 'Use the toolbar above to populate your collection.'}
                    </p>
                  </div>
                ) : (
                  <SortableContext items={allItemIds} strategy={verticalListSortingStrategy}>
                    <div className="py-4 px-4">
                      {tree.map(item => renderItem(item))}
                    </div>
                  </SortableContext>
                )}
              </div>
            </div>
          </div>

          <DragOverlay>
            {activeDragData?.isSource ? (
              <div className="bg-white dark:bg-[#242424] border-2 border-emerald-500 shadow-2xl rounded-2xl px-6 py-3 flex items-center gap-4 scale-105 opacity-90 backdrop-blur-sm">
                <div className="w-8 h-8 rounded-lg bg-emerald-50 dark:bg-emerald-500/10 flex items-center justify-center text-lg shadow-inner">
                  {activeDragData.count > 1 ? '📦' : activeDragData.type === 'folder' ? '📁' : '🔖'}
                </div>
                <span className="font-bold text-slate-900 dark:text-cream-100 truncate max-w-[200px]">
                  {activeDragData.count > 1
                    ? `${activeDragData.count} items`
                    : activeDragData.title}
                </span>
                <span className="text-[9px] font-black bg-emerald-500 text-white px-2 py-0.5 rounded-full uppercase shrink-0">Copy</span>
              </div>
            ) : activeItem ? (
              <div className="bg-white dark:bg-[#242424] border-2 border-primary-500 dark:border-terra-500 shadow-2xl rounded-2xl px-6 py-3 flex items-center gap-4 scale-105 opacity-90 backdrop-blur-sm">
                <div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-white/10 flex items-center justify-center text-xl shadow-inner">
                  {activeItem.type === 'folder' ? '📁' : '🔖'}
                </div>
                <span className="font-bold text-slate-900 dark:text-cream-100">{activeItem.title}</span>
              </div>
            ) : null}
          </DragOverlay>
        </DndContext>

        {/* Support Guide */}
        <div className="bg-slate-900/5 dark:bg-white/5 rounded-2xl p-6 border border-slate-900/5 dark:border-white/5 text-center">
          <div className="inline-flex items-center gap-2 bg-slate-900 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest mb-4">
            <span className="w-2 h-2 bg-green-400 rounded-full"></span>
            Interface Active
          </div>
          <p className="text-sm font-medium text-slate-600 dark:text-cream-500 leading-relaxed max-w-lg mx-auto">
            <span className="text-slate-900 dark:text-cream-100 font-bold">Double-click</span> any label to rename.
            <span className="text-slate-900 dark:text-cream-100 font-bold ml-1">Drag</span> items to adjust hierarchy.
            {showImportPanel && (
              <span className="ml-1">
                <span className="text-emerald-600 dark:text-emerald-400 font-bold">Select &amp; drag items</span> from the source panel into any folder to copy them. Drop onto a folder to place items inside it.
              </span>
            )}
            {' '}Changes only persist once <span className="text-primary-600 dark:text-terra-400 font-bold">committed</span>.
          </p>
        </div>
      </div>

      {/* Modern Add Item Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/80 dark:bg-black/80 backdrop-blur-sm flex items-center justify-center z-[100] p-6">
          <div className="bg-white dark:bg-[#242424] rounded-[2.5rem] border border-slate-200 dark:border-white/[0.06] p-10 w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-16 h-16 bg-primary-50 dark:bg-terra-500/10 rounded-2xl flex items-center justify-center text-3xl">
                {showAddModal === 'folder' ? '📁' : '🔖'}
              </div>
              <div>
                <h2 className="text-2xl font-black text-slate-900 dark:text-cream-100 tracking-tight">
                  Add New {showAddModal === 'folder' ? 'Folder' : 'Bookmark'}
                </h2>
                <p className="text-slate-500 dark:text-white/50 font-medium">Define your new organizational element below.</p>
              </div>
            </div>

            <form onSubmit={handleAddItem} className="space-y-6">
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-white/40 mb-2 ml-1">
                  Label Title
                </label>
                <input
                  type="text"
                  value={newItemTitle}
                  onChange={(e) => setNewItemTitle(e.target.value)}
                  className="w-full px-6 py-4 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] rounded-2xl focus:ring-4 focus:ring-primary-500/10 dark:focus:ring-terra-500/20 focus:border-primary-500 dark:focus:border-terra-500 focus:bg-white dark:focus:bg-[#242424] outline-none transition-all font-bold text-slate-900 dark:text-cream-100 placeholder:text-slate-300 dark:placeholder:text-white/30"
                  placeholder={showAddModal === 'folder' ? 'e.g., Research' : 'e.g., Google Search'}
                  required
                  autoFocus
                />
              </div>
              {showAddModal === 'bookmark' && (
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-white/40 mb-2 ml-1">
                    Resource URL
                  </label>
                  <input
                    type="url"
                    value={newItemUrl}
                    onChange={(e) => setNewItemUrl(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] rounded-2xl focus:ring-4 focus:ring-primary-500/10 dark:focus:ring-terra-500/20 focus:border-primary-500 dark:focus:border-terra-500 focus:bg-white dark:focus:bg-[#242424] outline-none transition-all font-bold text-slate-900 dark:text-cream-100 placeholder:text-slate-300 dark:placeholder:text-white/30"
                    placeholder="https://example.com/target"
                    required
                  />
                </div>
              )}
              <div className="flex gap-4 pt-4">
                <button
                  type="button"
                  onClick={() => {
                    setShowAddModal(null)
                    setNewItemTitle('')
                    setNewItemUrl('')
                  }}
                  className="flex-1 bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] hover:bg-slate-50 dark:hover:bg-white/5 text-slate-700 dark:text-white/70 py-4 rounded-2xl font-bold transition-all active:scale-95"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 bg-primary-600 dark:bg-terra-500 hover:bg-primary-700 dark:hover:bg-terra-600 text-white py-4 rounded-2xl font-bold transition-all shadow-lg shadow-primary-500/20 active:scale-95"
                >
                  Create Item
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ConfirmDialog
        isOpen={deleteConfirm.isOpen}
        title="Confirm Delete"
        message={deleteConfirm.title}
        confirmText="Delete"
        cancelText="Cancel"
        variant="danger"
        onConfirm={executeDelete}
        onCancel={() => setDeleteConfirm({ isOpen: false, title: '', masterIds: [] })}
      />

      <AlertDialog
        isOpen={saveErrorDialog.isOpen}
        title="Save Failed"
        message={saveErrorDialog.message}
        variant="error"
        onClose={() => setSaveErrorDialog({ isOpen: false, message: '' })}
      />
    </DashboardLayout>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter, useParams } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api, Collection, Folder, Bookmark, CollectionEvent, CollectionBrowser } from '@/lib/api'
import DashboardLayout from '@/components/DashboardLayout'
import ConfirmDialog from '@/components/ConfirmDialog'
import BookmarkTransfer from '@/components/BookmarkTransfer'

interface TreeItem {
  type: 'folder' | 'bookmark'
  id: string
  masterId: string
  title: string
  url?: string
  favicon?: string | null
  children?: TreeItem[]
  position: number
}

export default function CollectionViewPage() {
  const router = useRouter()
  const params = useParams()
  const collectionId = params.id as string
  const { user, token, isLoading, isPremium } = useAuth()
  const [collection, setCollection] = useState<Collection | null>(null)
  const [tree, setTree] = useState<TreeItem[]>([])
  const [events, setEvents] = useState<CollectionEvent[]>([])
  const [folderCount, setFolderCount] = useState(0)
  const [bookmarkCount, setBookmarkCount] = useState(0)
  const [loading, setLoading] = useState(true)
  const [eventLoading, setEventLoading] = useState(true)
  const [rollingBackEventId, setRollingBackEventId] = useState<string | null>(null)
  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set())
  const [searchQuery, setSearchQuery] = useState('')
  const [notice, setNotice] = useState<{ type: 'success' | 'error'; message: string } | null>(null)
  const [showArchiveModal, setShowArchiveModal] = useState(false)
  const [archiveLoading, setArchiveLoading] = useState(false)
  const [archiveBrowsers, setArchiveBrowsers] = useState<CollectionBrowser[]>([])
  const [archiveCheckDone, setArchiveCheckDone] = useState(false)
  const [confirmDialog, setConfirmDialog] = useState<{ isOpen: boolean; eventId: string | null }>({ isOpen: false, eventId: null })

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
  }, [isLoading, user, router])

  useEffect(() => {
    if (token && collectionId) {
      loadCollection()
    }
  }, [token, collectionId])

  useEffect(() => {
    if (notice && notice.type === 'success') {
      window.scrollTo({ top: 0, behavior: 'smooth' })
    }
  }, [notice])

  async function loadCollection() {
    if (!token) return
    try {
      // Handle "default" alias - resolve to actual default collection ID
      let actualCollectionId = collectionId
      if (collectionId === 'default') {
        const collections = await api.getCollections(token)
        const defaultCollection = collections.collections.find(c => c.isDefault === 1)
        if (defaultCollection) {
          actualCollectionId = defaultCollection.id
          // Update URL to actual ID without reloading
          router.replace(`/collections/${actualCollectionId}`, undefined)
        }
      }

      const [data, eventsData] = await Promise.all([
        api.getCollection(token, actualCollectionId),
        isPremium ? api.getCollectionEvents(token, actualCollectionId) : Promise.resolve({ collection: null as unknown as Collection, events: [], count: 0 }),
      ])
      setCollection(data.collection)
      setEvents(eventsData.events || [])
      setFolderCount(data.folders.length)
      setBookmarkCount(data.bookmarks.length)

      const treeData = buildTree(data.folders, data.bookmarks)
      setTree(treeData)

      const topLevelIds = treeData
        .filter(item => item.type === 'folder')
        .map(item => item.masterId)
      setExpandedFolders(new Set(topLevelIds))
    } catch (error) {
      console.error('Failed to load collection:', error)
    } finally {
      setLoading(false)
      setEventLoading(false)
    }
  }

  const formatDate = (timestamp: number) => {
    // If timestamp is in seconds (before 2001-09-09 in ms), convert to milliseconds
    const ms = timestamp < 10000000000 ? timestamp * 1000 : timestamp
    return new Date(ms).toLocaleString('en-GB', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getEventLabel = (type: string) => {
    switch (type) {
      case 'INITIAL_IMPORT':
        return 'Initial Import'
      case 'MERGE_IMPORT':
        return 'Merge Import'
      case 'MANUAL_EDIT':
        return 'Manual Edit'
      default:
        return type
    }
  }

  const getEventTheme = (type: string) => {
    switch (type) {
      case 'INITIAL_IMPORT':
        return {
          icon: '🚀',
          badge: 'bg-blue-100 dark:bg-blue-500/15 text-blue-700 dark:text-blue-300',
          iconWrap: 'bg-blue-50 dark:bg-blue-500/10'
        }
      case 'MERGE_IMPORT':
        return {
          icon: '🔄',
          badge: 'bg-emerald-100 dark:bg-emerald-500/15 text-emerald-700 dark:text-emerald-300',
          iconWrap: 'bg-emerald-50 dark:bg-emerald-500/10'
        }
      case 'MANUAL_EDIT':
        return {
          icon: '✏️',
          badge: 'bg-purple-100 dark:bg-purple-500/15 text-purple-700 dark:text-purple-300',
          iconWrap: 'bg-purple-50 dark:bg-purple-500/10'
        }
      default:
        return {
          icon: '📝',
          badge: 'bg-slate-100 dark:bg-white/10 text-slate-700 dark:text-white/70',
          iconWrap: 'bg-slate-50 dark:bg-white/5'
        }
    }
  }

  const getEventSummary = (event: CollectionEvent) => {
    const details = event.details || {}
    const parts: string[] = []

    const foldersCreated = typeof details.foldersCreated === 'number' ? details.foldersCreated : null
    const foldersSkipped = typeof details.foldersSkipped === 'number' ? details.foldersSkipped : null
    const bookmarksCreated = typeof details.bookmarksCreated === 'number' ? details.bookmarksCreated : null
    const bookmarksSkipped = typeof details.bookmarksSkipped === 'number' ? details.bookmarksSkipped : null
    const applied = typeof details.applied === 'number' ? details.applied : null

    if (foldersCreated !== null) parts.push(`${foldersCreated} folders added`)
    if (bookmarksCreated !== null) parts.push(`${bookmarksCreated} bookmarks added`)
    if (foldersSkipped) parts.push(`${foldersSkipped} folders skipped`)
    if (bookmarksSkipped) parts.push(`${bookmarksSkipped} bookmarks skipped`)
    if (applied !== null) parts.push(`${applied} editor changes applied`)

    return parts.length > 0 ? parts.join(' • ') : `${event.changesCount} change${event.changesCount === 1 ? '' : 's'} recorded`
  }

  const collectFolderIds = (items: TreeItem[]): string[] => {
    return items.flatMap((item) => {
      if (item.type !== 'folder') return []
      return [item.masterId, ...(item.children ? collectFolderIds(item.children) : [])]
    })
  }

  const expandAllFolders = () => {
    setExpandedFolders(new Set(collectFolderIds(tree)))
  }

  const collapseAllFolders = () => {
    setExpandedFolders(new Set())
  }

  const handleRollbackEvent = (eventId: string) => {
    if (!token) return
    setConfirmDialog({ isOpen: true, eventId })
  }

  const executeRollbackEvent = async () => {
    const eventId = confirmDialog.eventId
    if (!token || !eventId) return
    setConfirmDialog({ isOpen: false, eventId: null })

    setRollingBackEventId(eventId)
    setNotice(null)
    try {
      const result = await api.rollbackCollectionEvent(token, collectionId, eventId)
      await loadCollection()
      setNotice({
        type: 'success',
        message: `Collection restored. ${result.restoredFolders} folders and ${result.restoredBookmarks} bookmarks were restored to the pre-event state.${result.deletedEvents > 0 ? ` ${result.deletedEvents} restore point${result.deletedEvents === 1 ? '' : 's'} were removed.` : ''}`
      })
    } catch (error) {
      console.error('Failed to rollback collection event:', error)
      setNotice({
        type: 'error',
        message: 'Failed to rollback this restore point. Please try again.'
      })
    } finally {
      setRollingBackEventId(null)
    }
  }

  const handleArchiveClick = async () => {
    if (!token || !collectionId) return
    setArchiveCheckDone(false)
    setArchiveBrowsers([])
    setShowArchiveModal(true)

    try {
      const data = await api.getCollectionBrowsers(token, collectionId)
      setArchiveBrowsers(data.browsers || [])
    } catch (error) {
      console.error('Failed to check browser usage:', error)
      setArchiveBrowsers([])
    } finally {
      setArchiveCheckDone(true)
    }
  }

  const handleConfirmArchive = async () => {
    if (!token || !collectionId) return
    setArchiveLoading(true)
    try {
      await api.archiveCollection(token, collectionId)
      setShowArchiveModal(false)
      setNotice({
        type: 'success',
        message: 'Collection has been archived. Your data will be kept for 30 days before permanent deletion.'
      })
      setTimeout(() => router.push('/collections'), 2000)
    } catch (error: any) {
      if (error?.code === 'COLLECTION_IN_USE') {
        setArchiveBrowsers(error.browsers || [])
      } else {
        setNotice({
          type: 'error',
          message: 'Failed to archive collection. Please try again.'
        })
        setShowArchiveModal(false)
      }
    } finally {
      setArchiveLoading(false)
    }
  }

  const buildTree = (folders: Folder[], bookmarks: Bookmark[]): TreeItem[] => {
    // Create a map of items by masterId
    const folderMap = new Map<string, TreeItem>()
    const rootItems: TreeItem[] = []

    // Convert folders to tree items
    folders.forEach(folder => {
      folderMap.set(folder.masterId, {
        type: 'folder',
        id: folder.id,
        masterId: folder.masterId,
        title: folder.title,
        children: [],
        position: folder.position ?? 0
      })
    })

    // Add bookmarks to their parent folders or root
    bookmarks.forEach(bookmark => {
      const item: TreeItem = {
        type: 'bookmark',
        id: bookmark.id,
        masterId: bookmark.masterId,
        title: bookmark.title,
        url: bookmark.url,
        favicon: bookmark.favicon,
        position: bookmark.position ?? 0
      }

      if (bookmark.masterParentId && folderMap.has(bookmark.masterParentId)) {
        folderMap.get(bookmark.masterParentId)!.children!.push(item)
      } else {
        rootItems.push(item)
      }
    })

    // Build folder hierarchy
    folders.forEach(folder => {
      const treeItem = folderMap.get(folder.masterId)!

      if (folder.masterParentId && folderMap.has(folder.masterParentId)) {
        folderMap.get(folder.masterParentId)!.children!.push(treeItem)
      } else {
        rootItems.push(treeItem)
      }
    })

    // Sort children by position (preserving original browser order)
    const sortChildren = (items: TreeItem[]) => {
      items.sort((a, b) => {
        // Sort purely by position to match browser extension order
        return (a.position ?? 0) - (b.position ?? 0)
      })
      items.forEach(item => {
        if (item.children) sortChildren(item.children)
      })
    }
    sortChildren(rootItems)

    return rootItems
  }

  const toggleFolder = (masterId: string) => {
    setExpandedFolders(prev => {
      const next = new Set(prev)
      if (next.has(masterId)) {
        next.delete(masterId)
      } else {
        next.add(masterId)
      }
      return next
    })
  }

  const filterItems = (items: TreeItem[], query: string): TreeItem[] => {
    if (!query.trim()) return items

    const lowerQuery = query.toLowerCase()

    return items.reduce<TreeItem[]>((acc, item) => {
      const matches = item.title.toLowerCase().includes(lowerQuery) ||
        (item.url && item.url.toLowerCase().includes(lowerQuery))

      if (item.type === 'folder' && item.children) {
        const filteredChildren = filterItems(item.children, query)
        if (filteredChildren.length > 0 || matches) {
          acc.push({
            ...item,
            children: filteredChildren
          })
        }
      } else if (matches) {
        acc.push(item)
      }

      return acc
    }, [])
  }

  const renderTreeItem = (item: TreeItem, depth: number = 0) => {
    const isExpanded = expandedFolders.has(item.masterId)

    if (item.type === 'folder') {
      return (
        <div key={item.masterId} className="select-none">
          <button
            onClick={() => toggleFolder(item.masterId)}
            className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-50 dark:hover:bg-white/5 rounded-2xl transition-all group/folder"
            style={{ paddingLeft: `${depth * 28 + 16}px` }}
          >
            <div className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${isExpanded ? 'bg-primary-50 dark:bg-terra-500/10 text-primary-600 dark:text-terra-400' : 'text-slate-400 dark:text-white/40 group-hover/folder:text-slate-600 dark:group-hover/folder:text-cream-500'}`}>
              <svg
                className={`w-3.5 h-3.5 transition-transform duration-300 ${isExpanded ? 'rotate-90' : ''}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
              </svg>
            </div>

            <div className="w-8 h-8 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center text-lg group-hover/folder:bg-white dark:group-hover/folder:bg-[#242424] group-hover/folder:shadow-sm transition-all">
              📁
            </div>

            <span className="font-bold text-slate-700 dark:text-white/70 group-hover/folder:text-slate-900 dark:group-hover/folder:text-cream-100 transition-colors">
              {item.title}
            </span>

            <div className="ml-auto flex items-center gap-3">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-300 dark:text-white/30 group-hover/folder:text-slate-400 dark:group-hover/folder:text-white/40 transition-colors">
                {item.children?.length || 0} items
              </span>
            </div>
          </button>

          <div className={`overflow-hidden transition-all duration-300 ease-in-out ${isExpanded ? 'max-h-[5000px] opacity-100' : 'max-h-0 opacity-0'}`}>
            {item.children && item.children.map(child => renderTreeItem(child, depth + 1))}
          </div>
        </div>
      )
    }

    return (
      <a
        key={item.masterId}
        href={item.url}
        target="_blank"
        rel="noopener noreferrer"
        className="flex items-center gap-4 px-4 py-3 hover:bg-primary-50/50 dark:hover:bg-terra-500/10 rounded-2xl transition-all group/bookmark"
        style={{ paddingLeft: `${depth * 28 + 48}px` }}
      >
        <div className="w-8 h-8 rounded-xl bg-white dark:bg-[#242424] border border-slate-100 dark:border-white/5 flex items-center justify-center shadow-sm group-hover/bookmark:border-primary-100 transition-all">
          {item.favicon ? (
            <img src={item.favicon} alt="" className="w-4 h-4 object-contain" />
          ) : (
            <span className="text-slate-400 dark:text-white/40 text-xs">🔖</span>
          )}
        </div>

        <div className="flex-1 min-w-0">
          <div className="text-sm font-bold text-slate-700 dark:text-white/70 group-hover/bookmark:text-primary-700 dark:group-hover/bookmark:text-terra-400 transition-colors truncate">
            {item.title}
          </div>
          {item.url && (
            <div className="text-[10px] font-medium text-slate-400 dark:text-white/40 truncate mt-0.5">
              {item.url.replace(/^https?:\/\/(www\.)?/, '')}
            </div>
          )}
        </div>

        <div className="opacity-0 group-hover/bookmark:opacity-100 transition-all translate-x-1 group-hover/bookmark:translate-x-0">
          <div className="w-8 h-8 rounded-lg bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] flex items-center justify-center text-primary-600 dark:text-terra-400 shadow-sm">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
            </svg>
          </div>
        </div>
      </a>
    )
  }

  if (isLoading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  const filteredTree = filterItems(tree, searchQuery)
  const filteredCount = (items: TreeItem[]): number => items.reduce((total, item) => total + 1 + (item.children ? filteredCount(item.children) : 0), 0)
  const visibleItemCount = filteredCount(filteredTree)
  const latestEvent = events[0]

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto">
        {token && collection && <BookmarkTransfer token={token} collectionId={collection.id} onImported={() => void loadCollection()} />}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 mb-10">
          <div className="flex items-center gap-5">
            <Link
              href="/collections"
              className="w-12 h-12 bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] rounded-2xl flex items-center justify-center text-slate-400 dark:text-white/40 hover:text-primary-600 dark:hover:text-terra-400 hover:border-primary-100 hover:shadow-lg hover:shadow-primary-500/5 transition-all group"
            >
              <svg className="w-6 h-6 group-hover:-translate-x-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </Link>
            <div>
              <h1 className="text-3xl font-black text-slate-900 dark:text-cream-100 tracking-tight">
                {loading ? 'Loading...' : collection?.name || 'Collection'}
              </h1>
              {collection?.description && (
                <p className="text-slate-500 dark:text-white/50 mt-1 font-medium">{collection.description}</p>
              )}
              <div className="mt-3 flex flex-wrap items-center gap-2">
                {collection?.isDefault ? (
                  <span className="inline-flex items-center rounded-full bg-slate-100 dark:bg-white/10 px-3 py-1 text-[11px] font-bold text-slate-700 dark:text-white/70 uppercase tracking-wider">
                    Master Collection
                  </span>
                ) : null}
                <span className="inline-flex items-center rounded-full bg-primary-50 dark:bg-terra-500/10 px-3 py-1 text-[11px] font-bold text-primary-700 dark:text-terra-300 uppercase tracking-wider">
                  {folderCount + bookmarkCount} saved items
                </span>
                {isPremium ? (
                  <span className="inline-flex items-center rounded-full bg-emerald-50 dark:bg-emerald-500/10 px-3 py-1 text-[11px] font-bold text-emerald-700 dark:text-emerald-300 uppercase tracking-wider">
                    {events.length} restore points
                  </span>
                ) : null}
              </div>
            </div>
          </div>
          <div className="shrink-0 flex items-center gap-3">
            {isPremium ? (
              <>
                <Link
                  href={`/collections/${collectionId}/edit`}
                  className="inline-flex items-center justify-center gap-2 bg-primary-600 dark:bg-terra-500 hover:bg-primary-700 dark:hover:bg-terra-600 text-white px-6 py-3 rounded-xl font-bold transition-all hover:shadow-lg shadow-primary-500/20 active:scale-95"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                  </svg>
                  Modify Collection
                </Link>
                {!collection?.isDefault && (
                  <button
                    onClick={handleArchiveClick}
                    className="inline-flex items-center justify-center gap-2 bg-slate-100 dark:bg-white/10 hover:bg-red-50 dark:hover:bg-red-500/10 text-slate-600 dark:text-white/60 hover:text-red-600 dark:hover:text-red-400 px-5 py-3 rounded-xl font-bold transition-all border border-slate-200 dark:border-white/[0.06] hover:border-red-200 dark:hover:border-red-500/20 active:scale-95"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" />
                    </svg>
                    Archive
                  </button>
                )}
              </>
            ) : (
              <Link
                href="/settings/subscription"
                className="inline-flex items-center justify-center gap-2 bg-primary-50 dark:bg-terra-500/10 border border-primary-100 text-primary-700 dark:text-terra-400 px-6 py-3 rounded-xl font-bold transition-all hover:bg-primary-100 active:scale-95"
              >
                <span className="text-lg">⭐</span>
                Upgrade to Edit
              </Link>
            )}
          </div>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 mb-8">
          <div className="bg-white dark:bg-[#242424] rounded-[1.75rem] border border-slate-200 dark:border-white/[0.06] p-6 shadow-sm">
            <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 dark:text-white/40">Folders</div>
            <div className="mt-3 text-3xl font-black text-slate-900 dark:text-cream-100">{folderCount}</div>
          </div>
          <div className="bg-white dark:bg-[#242424] rounded-[1.75rem] border border-slate-200 dark:border-white/[0.06] p-6 shadow-sm">
            <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 dark:text-white/40">Bookmarks</div>
            <div className="mt-3 text-3xl font-black text-slate-900 dark:text-cream-100">{bookmarkCount}</div>
          </div>
          <div className="bg-white dark:bg-[#242424] rounded-[1.75rem] border border-slate-200 dark:border-white/[0.06] p-6 shadow-sm">
            <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 dark:text-white/40">Restore Points</div>
            <div className="mt-3 text-3xl font-black text-slate-900 dark:text-cream-100">{events.length}</div>
            <a href="#restore-points" className="mt-2 inline-flex items-center gap-1 text-sm font-semibold text-primary-600 dark:text-terra-400 hover:text-primary-700 dark:hover:text-terra-300 underline decoration-primary-300 dark:decoration-terra-500/40 underline-offset-2 transition-colors">View Restore Points <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg></a>
          </div>
          <div className="bg-white dark:bg-[#242424] rounded-[1.75rem] border border-slate-200 dark:border-white/[0.06] p-6 shadow-sm">
            <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 dark:text-white/40">Latest Activity</div>
            <div className="mt-3 text-lg font-black text-slate-900 dark:text-cream-100 leading-tight">
              {latestEvent ? getEventLabel(latestEvent.type) : 'No activity yet'}
            </div>
            <div className="mt-2 text-sm text-slate-500 dark:text-white/50">
              {latestEvent ? formatDate(latestEvent.createdAt || latestEvent.timestamp) : 'Your next import or edit will appear here'}
            </div>
          </div>
        </div>

        {notice ? (
          <div className={`mb-8 rounded-[1.75rem] border px-6 py-5 shadow-sm ${notice.type === 'success' ? 'bg-emerald-50 dark:bg-emerald-500/10 border-emerald-200 dark:border-emerald-500/20 text-emerald-800 dark:text-emerald-200' : 'bg-red-50 dark:bg-red-500/10 border-red-200 dark:border-red-500/20 text-red-800 dark:text-red-200'}`}>
            <div className="flex items-start gap-3">
              <div className="mt-0.5 text-lg">{notice.type === 'success' ? '✅' : '⚠️'}</div>
              <div>
                <div className="font-bold">{notice.type === 'success' ? 'Collection updated' : 'Action failed'}</div>
                <div className="mt-1 text-sm opacity-90">{notice.message}</div>
              </div>
            </div>
          </div>
        ) : null}

        <div className="mb-8 bg-white dark:bg-[#242424] rounded-[2rem] border border-slate-200 dark:border-white/[0.06] p-5 shadow-sm">
          <div className="flex flex-col lg:flex-row gap-4 lg:items-center lg:justify-between">
            <div className="relative flex-1 group">
              <div className="absolute left-4 top-1/2 -translate-y-1/2 flex items-center pointer-events-none">
                <svg
                  className="w-5 h-5 text-slate-400 dark:text-white/40 group-focus-within:text-primary-500 transition-colors"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search titles, folders, or URLs..."
                className="w-full pl-12 pr-6 py-4 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:border-primary-500 outline-none transition-all font-medium text-slate-900 dark:text-cream-100 placeholder:text-slate-400 dark:placeholder:text-white/40"
              />
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <button
                onClick={expandAllFolders}
                className="inline-flex items-center justify-center rounded-xl border border-slate-200 dark:border-white/[0.06] px-4 py-3 text-sm font-bold text-slate-700 dark:text-white/70 hover:bg-slate-50 dark:hover:bg-white/5 transition-all"
              >
                Expand all
              </button>
              <button
                onClick={collapseAllFolders}
                className="inline-flex items-center justify-center rounded-xl border border-slate-200 dark:border-white/[0.06] px-4 py-3 text-sm font-bold text-slate-700 dark:text-white/70 hover:bg-slate-50 dark:hover:bg-white/5 transition-all"
              >
                Collapse all
              </button>
              <div className="rounded-xl bg-slate-50 dark:bg-white/5 px-4 py-3 text-sm font-bold text-slate-600 dark:text-white/60">
                {visibleItemCount} visible
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-[#242424] rounded-[2rem] border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm">
          {loading ? (
            <div className="p-20 text-center">
              <div className="w-12 h-12 border-4 border-primary-100 border-t-primary-600 rounded-full animate-spin mx-auto"></div>
              <p className="text-slate-500 dark:text-white/50 mt-6 font-bold tracking-tight uppercase text-xs">Assembling Library...</p>
            </div>
          ) : filteredTree.length === 0 ? (
            <div className="p-20 text-center">
              <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
                <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 19a2 2 0 01-2-2V7a2 2 0 012-2h4l2 2h4a2 2 0 012 2v1m-6 9a3 3 0 100-6 3 3 0 000 6zm-7 0a3 3 0 110-6 3 3 0 010 6z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-slate-900 dark:text-cream-100 mb-2">
                {searchQuery ? 'No matches found' : 'This collection is empty'}
              </h3>
              <p className="text-slate-500 dark:text-white/50 max-w-xs mx-auto text-lg leading-relaxed">
                {searchQuery
                  ? 'Try expanding your search criteria'
                  : 'Add some bookmarks from your browser extension to get started.'}
              </p>
            </div>
          ) : (
            <div className="py-4">
              <div className="px-8 pb-4 mb-2 border-b border-slate-50 dark:border-white/5">
                <div className="flex items-center justify-between text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-white/40">
                  <span>Structure & Content</span>
                  <span>{searchQuery ? 'Filtered View' : 'Action'}</span>
                </div>
                <div className="mt-3 text-sm text-slate-500 dark:text-white/50">
                  {searchQuery
                    ? `Showing ${visibleItemCount} matching items for “${searchQuery}”`
                    : 'Browse your saved folders and links in browser order.'}
                </div>
              </div>
              <div className="px-4">
                {filteredTree.map(item => renderTreeItem(item))}
              </div>
            </div>
          )}
        </div>

        {isPremium && (
          <div id="restore-points" className="mt-8 bg-white dark:bg-[#242424] rounded-[2rem] border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm scroll-mt-24">
            <div className="px-8 py-6 border-b border-slate-100 dark:border-white/5 flex items-center justify-between gap-4">
              <div>
                <h2 className="text-lg font-bold text-slate-900 dark:text-cream-100">Collection Restore Points</h2>
                <p className="text-sm text-slate-500 dark:text-white/50 mt-1">Restore this collection to how it looked before each major import or edit. Great for undoing a bad import, merge, or batch edit.</p>
              </div>
              <div className="hidden sm:flex items-center rounded-xl bg-slate-50 dark:bg-white/5 px-4 py-3 text-xs font-bold uppercase tracking-[0.2em] text-slate-500 dark:text-white/40">
                {events.length} total checkpoints
              </div>
            </div>

            {eventLoading ? (
              <div className="p-8 text-sm text-slate-500 dark:text-white/50">Loading event history...</div>
            ) : events.length === 0 ? (
              <div className="p-10 text-center">
                <div className="w-16 h-16 rounded-full bg-slate-50 dark:bg-white/5 flex items-center justify-center mx-auto mb-5 text-2xl">🕘</div>
                <div className="text-lg font-bold text-slate-900 dark:text-cream-100">No restore points yet</div>
                <div className="mt-2 text-sm text-slate-500 dark:text-white/50 max-w-md mx-auto">Your next sync, import, or editor save will automatically create a rollback checkpoint here.</div>
              </div>
            ) : (
              <div className="divide-y divide-slate-100 dark:divide-white/5">
                {events.map((event, index) => (
                  <div key={event.eventId} className="px-8 py-6 flex flex-col xl:flex-row xl:items-center gap-5 xl:gap-6">
                    <div className="flex items-center gap-4 shrink-0">
                      <span className="text-xs font-black text-slate-300 dark:text-white/20 tabular-nums">{String(events.length - index).padStart(2, '0')}</span>
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shrink-0 ${getEventTheme(event.type).iconWrap}`}>
                        {getEventTheme(event.type).icon}
                      </div>
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className={`inline-flex items-center rounded-full px-3 py-1 text-xs font-bold ${getEventTheme(event.type).badge}`}>
                          {getEventLabel(event.type)}
                        </span>
                      </div>
                      <div className="mt-2 text-base font-bold text-slate-900 dark:text-cream-100">
                        {getEventSummary(event)}
                      </div>
                      <div className="mt-2 flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-slate-500 dark:text-white/50">
                        <span>{formatDate(event.createdAt || event.timestamp)}</span>
                        {event.sourceBrowser ? <span>Source: {event.sourceBrowser}</span> : <span>Source: Web editor</span>}
                        {event.sessionId ? <span>Session: {event.sessionId}</span> : null}
                        <span>{event.changesCount} change{event.changesCount === 1 ? '' : 's'}</span>
                      </div>
                      <div className="mt-3 text-sm text-slate-500 dark:text-white/50">
                        Restoring this point returns the collection to its state immediately before this event ran.
                      </div>
                    </div>
                    <div className="flex items-center gap-3 xl:justify-end">
                      <button
                        onClick={() => handleRollbackEvent(event.eventId)}
                        disabled={rollingBackEventId === event.eventId}
                        className="inline-flex items-center justify-center rounded-xl bg-slate-900 dark:bg-slate-800 px-5 py-3 text-sm font-bold text-white transition-all hover:bg-red-600 dark:hover:bg-red-500 disabled:opacity-50"
                      >
                        {rollingBackEventId === event.eventId ? 'Rolling back...' : 'Rollback to Before This'}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Archive Collection Modal */}
      {showArchiveModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in">
          <div className="bg-white dark:bg-[#2A2A2A] rounded-[2.5rem] p-10 w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200">
            {!archiveCheckDone ? (
              <div className="text-center py-8">
                <div className="w-12 h-12 border-4 border-slate-100 dark:border-white/10 border-t-red-500 rounded-full animate-spin mx-auto"></div>
                <p className="text-slate-500 dark:text-white/50 mt-6 font-bold">Checking browser usage...</p>
              </div>
            ) : archiveBrowsers.length > 0 ? (
              <>
                <div className="flex items-center gap-4 mb-6">
                  <div className="w-14 h-14 bg-amber-50 dark:bg-amber-500/10 rounded-2xl flex items-center justify-center">
                    <svg className="w-8 h-8 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4.5c-.77-.833-2.694-.833-3.464 0L3.34 16.5c-.77.833.192 2.5 1.732 2.5z" />
                    </svg>
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold text-slate-900 dark:text-cream-100">Cannot Archive Yet</h2>
                    <p className="text-slate-500 dark:text-white/50">This collection is currently in use</p>
                  </div>
                </div>

                <div className="bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/20 rounded-2xl p-5 mb-6">
                  <p className="text-sm text-amber-800 dark:text-amber-200 font-medium mb-4">
                    This collection cannot be archived because it is currently being used by the following browser{archiveBrowsers.length > 1 ? 's' : ''}. Please disconnect the collection from these browsers first.
                  </p>
                  <div className="space-y-3">
                    {archiveBrowsers.map((b) => (
                      <Link
                        key={b.browserInstanceId}
                        href={`/settings/browsers`}
                        onClick={() => setShowArchiveModal(false)}
                        className="flex items-center gap-4 bg-white dark:bg-[#242424] rounded-xl p-4 border border-amber-100 dark:border-amber-500/10 hover:border-amber-300 dark:hover:border-amber-500/30 transition-all group"
                      >
                        <div className="w-10 h-10 bg-slate-50 dark:bg-white/5 rounded-xl flex items-center justify-center">
                          <svg className="w-5 h-5 text-slate-500 dark:text-white/50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                          </svg>
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="font-bold text-slate-900 dark:text-cream-100 group-hover:text-primary-600 dark:group-hover:text-terra-400 transition-colors">
                            {b.nickname || b.browser}
                          </div>
                          <div className="text-xs text-slate-500 dark:text-white/50">
                            {b.browser} {b.os ? `on ${b.os}` : ''}
                          </div>
                        </div>
                        <svg className="w-5 h-5 text-slate-400 dark:text-white/30 group-hover:text-primary-600 dark:group-hover:text-terra-400 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                        </svg>
                      </Link>
                    ))}
                  </div>
                </div>

                <button
                  onClick={() => setShowArchiveModal(false)}
                  className="w-full bg-slate-100 dark:bg-white/10 hover:bg-slate-200 dark:hover:bg-white/15 text-slate-700 dark:text-white/70 py-4 rounded-2xl font-bold transition-all"
                >
                  Close
                </button>
              </>
            ) : (
              <>
                <div className="flex items-center gap-4 mb-6">
                  <div className="w-14 h-14 bg-red-50 dark:bg-red-500/10 rounded-2xl flex items-center justify-center">
                    <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" />
                    </svg>
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold text-slate-900 dark:text-cream-100">Archive Collection</h2>
                    <p className="text-slate-500 dark:text-white/50">This action can be undone within 30 days</p>
                  </div>
                </div>

                <div className="bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-2xl p-5 mb-6">
                  <p className="text-sm text-red-800 dark:text-red-200 font-medium leading-relaxed">
                    Are you sure you want to archive <strong>{collection?.name}</strong>? This collection and all its bookmarks and folders will be moved to your archive.
                  </p>
                  <div className="mt-4 flex items-start gap-3">
                    <svg className="w-5 h-5 text-red-400 mt-0.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    <p className="text-sm text-red-700 dark:text-red-300 font-bold">
                      Your data will be kept for 30 days. After 30 days, the collection and all its contents will be permanently deleted from the database.
                    </p>
                  </div>
                </div>

                <div className="flex gap-4">
                  <button
                    onClick={() => setShowArchiveModal(false)}
                    className="flex-1 bg-slate-100 dark:bg-white/10 hover:bg-slate-200 dark:hover:bg-white/15 text-slate-700 dark:text-white/70 py-4 rounded-2xl font-bold transition-all"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleConfirmArchive}
                    disabled={archiveLoading}
                    className="flex-[2] bg-red-600 hover:bg-red-700 disabled:bg-red-300 dark:disabled:bg-red-500/30 text-white py-4 rounded-2xl font-bold transition-all shadow-lg shadow-red-500/25"
                  >
                    {archiveLoading ? (
                      <span className="flex items-center justify-center gap-2">
                        <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Archiving...
                      </span>
                    ) : 'Yes, Archive Collection'}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      <ConfirmDialog
        isOpen={confirmDialog.isOpen}
        title="Rollback Restore Point"
        message="Rollback this collection to the state before this event?\n\nWARNING: This restore point and ALL restore points after it will be permanently deleted. This cannot be undone."
        confirmText="Rollback"
        cancelText="Cancel"
        variant="warning"
        onConfirm={executeRollbackEvent}
        onCancel={() => setConfirmDialog({ isOpen: false, eventId: null })}
      />
    </DashboardLayout>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api, Collection } from '@/lib/api'
import DashboardLayout from '@/components/DashboardLayout'

export default function CollectionsPage() {
  const router = useRouter()
  const { user, token, isLoading, isPremium } = useAuth()
  const [collections, setCollections] = useState<Collection[]>([])
  const [collectionsLoading, setCollectionsLoading] = useState(true)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [newCollectionName, setNewCollectionName] = useState('')
  const [creating, setCreating] = useState(false)

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
  }, [isLoading, user, router])

  useEffect(() => {
    if (token) {
      loadCollections()
    }
  }, [token])

  async function loadCollections() {
    if (!token) return
    try {
      const data = await api.getCollections(token)
      // API returns { collections: [...], count, canCreate }
      setCollections(data.collections || [])
    } catch (error) {
      console.error('Failed to load collections:', error)
      setCollections([])
    } finally {
      setCollectionsLoading(false)
    }
  }

  const handleCreateCollection = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!token || !newCollectionName.trim()) return

    setCreating(true)
    try {
      await api.createCollection(token, newCollectionName.trim())
      setShowCreateModal(false)
      setNewCollectionName('')
      loadCollections()
    } catch (error) {
      console.error('Failed to create collection:', error)
    } finally {
      setCreating(false)
    }
  }

  if (isLoading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  return (
    <DashboardLayout>
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-10">
          <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-cream-100">Collections</h1>
            <p className="text-slate-600 dark:text-cream-500 mt-2 text-lg">Organize your bookmarks into custom collections</p>
          </div>
          {isPremium && (
            <button
              onClick={() => setShowCreateModal(true)}
              className="inline-flex items-center justify-center gap-2 bg-primary-600 hover:bg-primary-700 dark:bg-terra-500 dark:hover:bg-terra-600 text-white px-6 py-3 rounded-xl font-bold transition-all hover:shadow-lg shadow-primary-500/20 dark:shadow-terra-500/10"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
              New Collection
            </button>
          )}
        </div>

        {/* Collection Slots Counter */}
        <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] p-8 mb-8 shadow-sm">
          <div className="flex flex-col sm:flex-row items-center justify-between gap-6">
            <div>
              <h2 className="text-xl font-bold text-slate-900 dark:text-cream-100">Collection Slots</h2>
              <p className="text-slate-500 dark:text-white/50 mt-2 font-medium">
                {isPremium
                  ? 'You have unlimited collections'
                  : `Free plan usage: ${collections.length} of ${user.collectionLimit} slots used`
                }
              </p>
            </div>
            <div className="flex items-center gap-6">
              <div className="text-right">
                <div className="text-4xl font-black text-slate-900 dark:text-cream-100 tracking-tight">
                  {collections.length} / {user.collectionLimit >= 50 ? '∞' : user.collectionLimit}
                </div>
                <div className="text-xs text-slate-400 dark:text-white/40 font-bold uppercase tracking-widest mt-1">Active Slots</div>
              </div>
            </div>
          </div>
        </div>

        {/* Collections Grid */}
        {collectionsLoading ? (
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-100 dark:border-white/5 p-8 shadow-sm animate-pulse">
                <div className="w-12 h-12 bg-slate-100 dark:bg-white/10 rounded-2xl mb-6"></div>
                <div className="h-6 bg-slate-100 dark:bg-white/10 rounded-xl w-3/4 mb-4"></div>
                <div className="h-4 bg-slate-50 dark:bg-white/5 rounded-lg w-1/2"></div>
              </div>
            ))}
          </div>
        ) : collections.length === 0 ? (
          <div className="text-center py-24 bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] border-dashed">
            <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
              <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <h3 className="text-xl font-bold text-slate-900 dark:text-cream-100 mb-2">No collections yet</h3>
            <p className="text-slate-500 dark:text-white/50 max-w-sm mx-auto">Your Master Collection will appear here after your first sync from the browser extension.</p>
          </div>
        ) : (
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {collections.map((collection) => (
              <div
                key={collection.id}
                className="group bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] p-8 shadow-sm hover:shadow-xl hover:shadow-primary-500/5 dark:hover:shadow-none hover:border-primary-100 dark:hover:border-terra-500/20 transition-all"
              >
                <div className="flex items-start justify-between mb-6">
                  <div className="w-12 h-12 bg-primary-50 dark:bg-terra-500/10 rounded-2xl flex items-center justify-center">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                    </svg>
                  </div>
                  {collection.isDefault === 1 && (
                    <span className="bg-primary-100 dark:bg-terra-500/15 text-primary-700 dark:text-terra-300 text-[10px] font-black uppercase tracking-wider px-2.5 py-1 rounded-full">
                      Default
                    </span>
                  )}
                </div>

                <div className="mb-8">
                  <h3 className="text-xl font-bold text-slate-900 dark:text-cream-100 mb-2">
                    {collection.name}
                  </h3>
                  <p className="text-sm text-slate-500 dark:text-white/50 line-clamp-2">
                    {collection.description || 'Self-contained bookmark collection from your synced browsers.'}
                  </p>
                </div>

                <Link
                  href={`/collections/${collection.id}`}
                  className="w-full inline-flex items-center justify-center bg-terra-500 hover:bg-terra-600 dark:bg-terra-500 dark:hover:bg-terra-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold transition-all shadow-md shadow-terra-500/10"
                >
                  Open
                </Link>
              </div>
            ))}
          </div>
        )}

        {/* Upgrade prompt for free users */}
        {!isPremium && collections.length > 0 && (
          <div className="mt-12 relative overflow-hidden bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] rounded-3xl p-10 text-center shadow-lg shadow-slate-200/50">
            <div className="relative z-10">
              <h3 className="text-2xl font-bold text-slate-900 dark:text-cream-100 mb-3">Want multiple collections?</h3>
              <p className="text-slate-600 dark:text-cream-500 mb-8 max-w-xl mx-auto text-lg leading-relaxed">
                Upgrade to Premium to create unlimited collections, use the drag-drop editor,
                and get priority support for your entire bookmark library.
              </p>
              <Link
                href="/settings/subscription"
                className="inline-flex items-center justify-center gap-2 bg-primary-600 hover:bg-primary-700 dark:bg-terra-500 dark:hover:bg-terra-600 text-white px-10 py-4 rounded-xl font-bold text-lg transition-all hover:shadow-xl shadow-primary-500/30 dark:shadow-terra-500/10"
              >
                Start Premium Journey
              </Link>
            </div>
            {/* Decorative background elements */}
            <div className="absolute top-0 left-0 w-32 h-32 bg-primary-50 dark:bg-terra-500/10 rounded-full blur-3xl -translate-y-12 -translate-x-12"></div>
            <div className="absolute bottom-0 right-0 w-48 h-48 bg-teal-50 dark:bg-teal-500/10 rounded-full blur-3xl translate-y-12 translate-x-12"></div>
          </div>
        )}
      </div>

      {/* Create Collection Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 transition-all animate-in fade-in">
          <div className="bg-white dark:bg-[#2A2A2A] rounded-[2.5rem] p-10 w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-14 h-14 bg-primary-50 dark:bg-terra-500/10 rounded-2xl flex items-center justify-center">
                <svg className="w-8 h-8 text-primary-600 dark:text-terra-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </div>
              <div>
                <h2 className="text-2xl font-bold text-slate-900 dark:text-cream-100">Create Collection</h2>
                <p className="text-slate-500 dark:text-white/50">Add a new organization to your library</p>
              </div>
            </div>

            <form onSubmit={handleCreateCollection} className="space-y-8">
              <div>
                <label htmlFor="name" className="block text-sm font-bold text-slate-700 dark:text-white/70 mb-3 ml-1">
                  Collection Name
                </label>
                <input
                  id="name"
                  type="text"
                  value={newCollectionName}
                  onChange={(e) => setNewCollectionName(e.target.value)}
                  className="w-full px-6 py-4 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-2xl focus:ring-4 focus:ring-primary-500/10 focus:border-primary-500 focus:bg-white dark:focus:bg-white/5 outline-none transition-all text-lg font-medium text-slate-900 dark:text-cream-100 placeholder:text-slate-400 dark:placeholder:text-white/40"
                  placeholder="e.g. Work Resources, Research..."
                  required
                />
              </div>
              <div className="flex gap-4 pt-4">
                <button
                  type="button"
                  onClick={() => setShowCreateModal(false)}
                  className="flex-1 bg-slate-100 dark:bg-white/10 hover:bg-slate-200 dark:hover:bg-white/15 text-slate-700 dark:text-white/70 py-4 rounded-2xl font-bold transition-all"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={creating}
                  className="flex-[2] bg-primary-600 hover:bg-primary-700 dark:bg-terra-500 dark:hover:bg-terra-600 disabled:bg-primary-300 dark:disabled:bg-terra-500/30 text-white py-4 rounded-2xl font-bold transition-all shadow-lg shadow-primary-500/25 dark:shadow-terra-500/10"
                >
                  {creating ? (
                    <span className="flex items-center justify-center gap-2">
                      <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Creating...
                    </span>
                  ) : 'Create Collection'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </DashboardLayout>
  )
}

