          <p className="text-ink-400 dark:text-white/40 mt-2.5 text-[15px]">Sign in to access your bookmarks</p>
        </div>

        {/* Login Form Card */}
        <div className="bg-white dark:bg-[#242424] p-8 rounded-2xl border border-cream-300 dark:border-white/10 shadow-soft">
