'use client'

import { useEffect, useState } from 'react'
import { useRouter, useParams } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api, SessionSummary, Folder, Bookmark } from '@/lib/api'
import DashboardLayout from '@/components/DashboardLayout'
import ConfirmDialog from '@/components/ConfirmDialog'
import AlertDialog from '@/components/AlertDialog'

export default function SessionDetailPage() {
  const router = useRouter()
  const params = useParams()
  const sessionId = params.id as string
  const { user, token, isLoading, isPremium } = useAuth()
  const [session, setSession] = useState<SessionSummary | null>(null)
  const [folders, setFolders] = useState<Folder[]>([])
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([])
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [isRolledBack, setIsRolledBack] = useState(false)
  const [confirmDialog, setConfirmDialog] = useState<{ isOpen: boolean; action: 'rollback' | 'restore' | null }>({ isOpen: false, action: null })
  const [alertDialog, setAlertDialog] = useState<{ isOpen: boolean; title: string; message: string; variant: 'success' | 'error' }>({ isOpen: false, title: '', message: '', variant: 'success' })

  async function loadSession() {
    if (!token) return
    try {
      const data = await api.getSession(token, sessionId)
      setSession(data.session)
      setFolders(data.folders)
      setBookmarks(data.bookmarks)
    } catch (error) {
      console.error('Failed to load session:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
    if (!isLoading && user && !isPremium) {
      router.push('/dashboard')
    }
  }, [isLoading, user, isPremium, router])

  useEffect(() => {
    if (token && sessionId && isPremium) {
      loadSession()
    }
  }, [token, sessionId, isPremium])


  const handleRollback = () => {
    if (!token) return
    setConfirmDialog({ isOpen: true, action: 'rollback' })
  }

  const handleRestore = () => {
    if (!token) return
    setConfirmDialog({ isOpen: true, action: 'restore' })
  }

  const executeConfirmAction = async () => {
    if (!token) return
    const action = confirmDialog.action
    setConfirmDialog({ isOpen: false, action: null })

    setActionLoading(true)
    try {
      if (action === 'rollback') {
        const result = await api.rollbackSession(token, sessionId)
        setIsRolledBack(true)
        setAlertDialog({
          isOpen: true,
          title: 'Session Rolled Back',
          message: `Successfully rolled back ${result.rolledBackCount} items.`,
          variant: 'success'
        })
      } else if (action === 'restore') {
        const result = await api.restoreSession(token, sessionId)
        setIsRolledBack(false)
        setAlertDialog({
          isOpen: true,
          title: 'Session Restored',
          message: `Successfully restored ${result.restoredCount} items.`,
          variant: 'success'
        })
      }
    } catch (error) {
      console.error(`Failed to ${action} session:`, error)
      setAlertDialog({
        isOpen: true,
        title: 'Action Failed',
        message: `Failed to ${action} session. Please try again.`,
        variant: 'error'
      })
    } finally {
      setActionLoading(false)
    }
  }

  const formatDate = (timestamp: number) => {
    // Handle both seconds (Unix) and milliseconds timestamps
    const ms = timestamp < 1e12 ? timestamp * 1000 : timestamp
    return new Date(ms).toLocaleString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    })
  }

  const getSessionTypeLabel = (type: string) => {
    switch (type) {
      case 'INITIAL_IMPORT':
        return { label: 'Initial Sync', color: 'bg-blue-100 text-blue-700 dark:bg-blue-500/15 dark:text-blue-300', icon: '🚀' }
      case 'MERGE_IMPORT':
        return { label: 'Merge', color: 'bg-green-100 text-green-700 dark:bg-green-500/15 dark:text-green-300', icon: '🔄' }
      case 'MANUAL_EDIT':
        return { label: 'Manual Edit', color: 'bg-purple-100 text-purple-700 dark:bg-purple-500/15 dark:text-purple-300', icon: '✏️' }
      default:
        return { label: type, color: 'bg-gray-100 text-gray-700 dark:bg-gray-500/15 dark:text-gray-300', icon: '📝' }
    }
  }

  if (isLoading || !user || !isPremium) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  const typeInfo = session ? getSessionTypeLabel(session.type) : null

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 mb-10">
          <div className="flex items-center gap-5">
            <Link
              href="/sessions"
              className="w-12 h-12 bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] rounded-2xl flex items-center justify-center text-slate-400 dark:text-white/40 hover:text-primary-600 dark:hover:text-terra-400 hover:border-primary-100 hover:shadow-lg hover:shadow-primary-500/5 transition-all group"
            >
              <svg className="w-6 h-6 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </Link>
            <div>
              <h1 className="text-3xl font-black text-slate-900 dark:text-cream-100 tracking-tight">Session Details</h1>
              <p className="text-slate-500 dark:text-white/50 mt-1 font-medium">
                {loading ? 'Analyzing data...' : `Sync from ${session?.sourceBrowser || 'Unknown Source'}`}
              </p>
            </div>
          </div>
        </div>

        {loading ? (
          <div className="bg-white dark:bg-[#242424] rounded-[2.5rem] border border-slate-200 dark:border-white/[0.06] p-20 text-center shadow-sm">
            <div className="w-12 h-12 border-4 border-primary-100 border-t-primary-600 rounded-full animate-spin mx-auto"></div>
            <p className="text-slate-500 dark:text-white/50 mt-6 font-bold tracking-tight uppercase text-xs">Retrieving session manifest...</p>
          </div>
        ) : session ? (
          <>
            {/* Session Info card */}
            <div className={`relative overflow-hidden bg-white dark:bg-[#242424] rounded-[2.5rem] border p-10 mb-8 shadow-sm transition-all ${isRolledBack ? 'border-red-200 dark:border-red-500/30 bg-red-50/50 dark:bg-red-500/10' : 'border-slate-200 dark:border-white/[0.06]'}`}>
              {isRolledBack && (
                <div className="mb-8 p-4 bg-red-100/50 dark:bg-red-500/15 border border-red-200 dark:border-red-500/30 rounded-2xl flex items-center gap-3 text-red-700 dark:text-red-300 font-bold text-sm animate-in fade-in slide-in-from-top-2">
                  <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                  This session has been rolled back and is hidden from your collection.
                </div>
              )}

              <div className="grid md:grid-cols-2 gap-10">
                <div>
                  <div className="flex items-center gap-5 mb-6">
                    <div className="w-16 h-16 bg-slate-50 dark:bg-white/5 rounded-2xl flex items-center justify-center text-4xl shadow-sm border border-slate-100 dark:border-white/5">
                      {typeInfo?.icon}
                    </div>
                    <div>
                      <span className={`text-[10px] font-black uppercase tracking-widest px-2.5 py-1 rounded-full ${typeInfo?.color}`}>
                        {typeInfo?.label}
                      </span>
                      <h2 className="text-2xl font-black text-slate-900 dark:text-cream-100 mt-2 tracking-tight">
                        {session.sourceBrowser || 'Unknown'}
                      </h2>
                    </div>
                  </div>
                  <div className="space-y-3">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-slate-400 dark:text-white/40 font-bold uppercase tracking-tighter text-xs">Sync Date</span>
                      <span className="text-slate-900 dark:text-cream-100 font-bold">{formatDate(session.timestamp)}</span>
                    </div>
                    <div className="flex items-center justify-between text-sm pt-3 border-t border-slate-50 dark:border-white/5">
                      <span className="text-slate-400 dark:text-white/40 font-bold uppercase tracking-tighter text-xs">Signature</span>
                      <span className="text-slate-900 dark:text-cream-100 font-mono text-xs bg-slate-100 dark:bg-white/10 px-2 py-1 rounded-md">{session.sessionId.slice(0, 12)}</span>
                    </div>
                  </div>
                </div>
                <div>
                  <h3 className="text-xs font-black text-slate-400 dark:text-white/40 uppercase tracking-[0.2em] mb-4">Payload Summary</h3>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="bg-slate-50 dark:bg-white/5 rounded-[2rem] p-5 text-center border border-slate-100/50 dark:border-white/5">
                      <div className="text-2xl font-black text-slate-900 dark:text-cream-100">{session.itemCount}</div>
                      <div className="text-[10px] font-black text-slate-400 dark:text-white/40 uppercase tracking-tighter mt-1">Total</div>
                    </div>
                    <div className="bg-slate-50 dark:bg-white/5 rounded-[2rem] p-5 text-center border border-slate-100/50 dark:border-white/5">
                      <div className="text-2xl font-black text-slate-900 dark:text-cream-100">{session.foldersAdded}</div>
                      <div className="text-[10px] font-black text-slate-400 dark:text-white/40 uppercase tracking-tighter mt-1">Folders</div>
                    </div>
                    <div className="bg-slate-50 dark:bg-white/5 rounded-[2rem] p-5 text-center border border-slate-100/50 dark:border-white/5">
                      <div className="text-2xl font-black text-slate-900 dark:text-cream-100">{session.bookmarksAdded}</div>
                      <div className="text-[10px] font-black text-slate-400 dark:text-white/40 uppercase tracking-tighter mt-1">Links</div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Action Area */}
              <div className="mt-10 pt-10 border-t border-slate-100 dark:border-white/5 flex flex-col sm:flex-row items-center justify-between gap-4">
                <p className="text-slate-500 dark:text-white/50 text-sm font-medium">Use rollback to undo an accidental sync or import.</p>
                <div className="flex gap-4 w-full sm:w-auto">
                  {isRolledBack ? (
                    <button
                      onClick={handleRestore}
                      disabled={actionLoading}
                      className="flex-1 sm:flex-initial bg-green-600 dark:bg-green-500 hover:bg-green-700 dark:hover:bg-green-600 disabled:opacity-50 text-white px-8 py-3.5 rounded-2xl font-bold transition-all shadow-lg shadow-green-500/20 active:scale-95 flex items-center justify-center gap-2"
                    >
                      {actionLoading ? (
                        <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
                      ) : (
                        <>
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                          </svg>
                          Restore Data
                        </>
                      )}
                    </button>
                  ) : (
                    <button
                      onClick={handleRollback}
                      disabled={actionLoading}
                      className="flex-1 sm:flex-initial bg-slate-900 dark:bg-slate-800 hover:bg-red-600 dark:hover:bg-red-500 disabled:opacity-50 text-white px-8 py-3.5 rounded-2xl font-bold transition-all shadow-lg shadow-slate-900/10 active:scale-95 flex items-center justify-center gap-2"
                    >
                      {actionLoading ? (
                        <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
                      ) : (
                        <>
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" />
                          </svg>
                          Rollback Sync
                        </>
                      )}
                    </button>
                  )}
                </div>
              </div>
            </div>

            {/* Content list card */}
            <div className="bg-white dark:bg-[#242424] rounded-[2.5rem] border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm">
              <div className="px-10 py-6 border-b border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5 flex items-center justify-between">
                <h3 className="font-bold text-slate-900 dark:text-cream-100">Items Synchronized</h3>
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-white/40">{folders.length + bookmarks.length} elements</span>
              </div>

              <div className="max-h-[500px] overflow-y-auto custom-scrollbar">
                {folders.length === 0 && bookmarks.length === 0 ? (
                  <div className="p-20 text-center text-slate-400 dark:text-white/40 font-medium">
                    No items recorded for this session.
                  </div>
                ) : (
                  <div className="divide-y divide-slate-100 dark:divide-white/5">
                    {/* Folders */}
                    {folders.map((folder) => (
                      <div key={folder.id} className="px-10 py-4 flex items-center gap-4 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors group">
                        <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center text-xl group-hover:bg-white dark:group-hover:bg-[#242424] group-hover:shadow-sm transition-all shrink-0">📁</div>
                        <div className="flex-1">
                          <span className="font-bold text-slate-700 dark:text-white/70">{folder.title}</span>
                          <div className="text-[10px] font-black text-slate-400 dark:text-white/40 uppercase tracking-tighter mt-0.5">Directory</div>
                        </div>
                      </div>
                    ))}

                    {/* Bookmarks */}
                    {bookmarks.map((bookmark) => (
                      <div key={bookmark.id} className="px-10 py-4 flex items-center gap-4 hover:bg-primary-50/30 dark:hover:bg-terra-500/10 transition-colors group">
                        <div className="w-10 h-10 rounded-xl bg-white dark:bg-[#242424] border border-slate-100 dark:border-white/5 flex items-center justify-center shadow-sm group-hover:border-primary-100 transition-all shrink-0">
                          {bookmark.favicon ? (
                            <img src={bookmark.favicon} alt="" className="w-5 h-5 object-contain" />
                          ) : (
                            <span className="text-xl">🔖</span>
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="font-bold text-slate-700 dark:text-white/70 truncate group-hover:text-primary-700 dark:group-hover:text-terra-400 transition-colors">{bookmark.title}</div>
                          <div className="text-[10px] font-medium text-slate-400 dark:text-white/40 truncate mt-0.5">{bookmark.url}</div>
                        </div>
                        <a
                          href={bookmark.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="w-10 h-10 flex items-center justify-center rounded-xl text-slate-300 dark:text-white/30 hover:text-primary-600 dark:hover:text-terra-400 hover:bg-white dark:hover:bg-[#242424] hover:shadow-sm border border-transparent hover:border-slate-100 dark:hover:border-white/5 transition-all"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                          </svg>
                        </a>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="bg-white dark:bg-[#242424] rounded-[2.5rem] border border-slate-200 dark:border-white/[0.06] p-20 text-center shadow-sm">
            <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
              <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h3 className="text-2xl font-black text-slate-900 dark:text-cream-100 mb-4">Manifest Not Found</h3>
            <p className="text-slate-500 dark:text-white/50 max-w-xs mx-auto text-lg leading-relaxed">This session trace could not be located in our system.</p>
            <Link
              href="/sessions"
              className="inline-flex items-center gap-2 mt-8 text-primary-600 dark:text-terra-400 hover:text-primary-700 dark:hover:text-terra-300 font-black uppercase tracking-widest text-xs"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" />
              </svg>
              Back to History
            </Link>
          </div>
        )}
      </div>

      <ConfirmDialog
        isOpen={confirmDialog.isOpen}
        title={confirmDialog.action === 'rollback' ? 'Rollback Session' : 'Restore Session'}
        message={
          confirmDialog.action === 'rollback'
            ? 'Are you sure you want to rollback this session?\n\nAll items from this sync will be removed from your Master Collection.'
            : 'Are you sure you want to restore this session?\n\nAll items will be added back to your Master Collection.'
        }
        confirmText={confirmDialog.action === 'rollback' ? 'Rollback' : 'Restore'}
        cancelText="Cancel"
        variant={confirmDialog.action === 'rollback' ? 'danger' : 'warning'}
        onConfirm={executeConfirmAction}
        onCancel={() => setConfirmDialog({ isOpen: false, action: null })}
      />

      <AlertDialog
        isOpen={alertDialog.isOpen}
        title={alertDialog.title}
        message={alertDialog.message}
        variant={alertDialog.variant}
        onClose={() => setAlertDialog({ ...alertDialog, isOpen: false })}
      />
    </DashboardLayout>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api, SessionSummary } from '@/lib/api'
import DashboardLayout from '@/components/DashboardLayout'

export default function SessionsPage() {
  const router = useRouter()
  const { user, token, isLoading, isPremium } = useAuth()
  const [sessions, setSessions] = useState<SessionSummary[]>([])
  const [sessionsLoading, setSessionsLoading] = useState(true)

  async function loadSessions() {
    if (!token) return
    try {
      const data = await api.getSessions(token)
      setSessions(data.sessions || [])
    } catch (error) {
      console.error('Failed to load sessions:', error)
    } finally {
      setSessionsLoading(false)
    }
  }

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
    if (!isLoading && user && !isPremium) {
      router.push('/dashboard')
    }
  }, [isLoading, user, isPremium, router])

  useEffect(() => {
    if (token && isPremium) {
      loadSessions()
    }
  }, [token, isPremium])


  const formatDate = (timestamp: number) => {
    // Handle both seconds (Unix) and milliseconds timestamps
    const ms = timestamp < 1e12 ? timestamp * 1000 : timestamp
    return new Date(ms).toLocaleString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getSessionTypeLabel = (type: string) => {
    switch (type) {
      case 'INITIAL_IMPORT':
        return { label: 'Initial Sync', color: 'bg-blue-100 dark:bg-blue-500/15 text-blue-700 dark:text-blue-300' }
      case 'MERGE_IMPORT':
        return { label: 'Merge', color: 'bg-green-100 dark:bg-green-500/15 text-green-700 dark:text-green-300' }
      case 'MANUAL_EDIT':
        return { label: 'Manual Edit', color: 'bg-purple-100 dark:bg-purple-500/15 text-purple-700 dark:text-purple-300' }
      default:
        return { label: type, color: 'bg-gray-100 text-gray-700' }
    }
  }

  if (isLoading || !user || !isPremium) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-10">
          <h1 className="text-3xl font-bold text-slate-900 dark:text-cream-100">Session History</h1>
          <p className="text-slate-600 dark:text-cream-500 mt-2 text-lg">View and rollback previous sync operations</p>
        </div>

        {/* Sessions List */}
        <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm">
          {sessionsLoading ? (
            <div className="p-12 text-center">
              <div className="w-12 h-12 border-3 border-primary-100 dark:border-terra-500/20 border-t-primary-600 dark:border-t-terra-400 rounded-full animate-spin mx-auto"></div>
              <p className="text-slate-500 dark:text-white/50 mt-6 font-medium">Loading history...</p>
            </div>
          ) : sessions.length === 0 ? (
            <div className="p-16 text-center">
              <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
                <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-slate-900 dark:text-cream-100 mb-2">No sessions yet</h3>
              <p className="text-slate-500 dark:text-white/50 max-w-xs mx-auto">
                Your sync history will appear here after you connect a browser extension.
              </p>
            </div>
          ) : (
            <div className="divide-y divide-slate-100 dark:divide-white/5">
              {sessions.map((session) => {
                const typeInfo = getSessionTypeLabel(session.type)
                return (
                  <Link
                    key={session.sessionId}
                    href={`/sessions/${session.sessionId}`}
                    className="group block p-6 hover:bg-slate-50 dark:hover:bg-white/5 transition-all"
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 rounded-2xl bg-slate-50 dark:bg-white/5 flex items-center justify-center group-hover:bg-white dark:group-hover:bg-[#2A2A2A] group-hover:shadow-md transition-all">
                          {session.type === 'INITIAL_IMPORT' ? (
                            <svg className="w-6 h-6 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                            </svg>
                          ) : session.type === 'MERGE_IMPORT' ? (
                            <svg className="w-6 h-6 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
                            </svg>
                          ) : (
                            <svg className="w-6 h-6 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                            </svg>
                          )}
                        </div>
                        <div>
                          <div className="flex items-center gap-3">
                            <span className="font-bold text-slate-900 dark:text-cream-100 group-hover:text-primary-600 dark:group-hover:text-terra-400 transition-colors">
                              {session.sourceBrowser || 'Web Editor'}
                            </span>
                            <span className={`text-[10px] font-black uppercase tracking-wider px-2.5 py-1 rounded-full ${typeInfo.color.replace('100', '100').replace('700', '700')}`}>
                              {typeInfo.label}
                            </span>
                          </div>
                          <div className="text-sm text-slate-500 dark:text-white/50 mt-1 font-medium italic">
                            {formatDate(session.timestamp)}
                          </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="text-lg font-black text-slate-900 dark:text-cream-100">
                          {session.itemCount.toLocaleString()}
                        </div>
                        <div className="text-xs text-slate-400 dark:text-white/40 font-bold uppercase tracking-tighter">
                          Items Synced
                        </div>
                      </div>
                    </div>
                  </Link>
                )
              })}
            </div>
          )}
        </div>

        {/* Info */}
        <div className="mt-8 relative overflow-hidden bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] rounded-3xl p-8 shadow-sm">
          <div className="relative z-10 flex gap-5">
            <div className="w-12 h-12 rounded-2xl bg-primary-50 dark:bg-terra-500/10 flex items-center justify-center shrink-0">
              <svg className="w-6 h-6 text-primary-600 dark:text-terra-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-900 dark:text-cream-100 mb-2">About Session Rollback</h3>
              <p className="text-slate-600 dark:text-cream-500 leading-relaxed">
                Mistakes happen. Rolling back a session will remove all bookmarks and folders that were added during that specific sync operation.
                Your Master Collection will return to its state prior to that sync, ensuring your library stays clean and organized.
              </p>
            </div>
          </div>
          <div className="absolute top-0 right-0 w-32 h-32 bg-primary-50 dark:bg-terra-500/10 rounded-full blur-3xl -translate-y-8 translate-x-8"></div>
        </div>
      </div>
    </DashboardLayout>
  )
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api, Bookmark, BrowserHistoryBrowserInfo, BrowserHistoryEntry, Folder } from '@/lib/api'
import DashboardLayout from '@/components/DashboardLayout'

interface SyncDetails {
  changesProcessed?: number
  bookmarksCreated?: number
  foldersCreated?: number
  bookmarksUpdated?: number
  foldersUpdated?: number
  bookmarksDeleted?: number
  foldersDeleted?: number
  bookmarksSkipped?: number
  foldersSkipped?: number
}

type BrowserHistoryDetail = BrowserHistoryEntry & {
  details?: SyncDetails | null
}

type FolderNode = Folder & {
  childFolders: FolderNode[]
  childBookmarks: Bookmark[]
}

export default function BrowserHistoryDetailPage() {
  const router = useRouter()
  const params = useParams()
  const browserInstanceId = params.browserInstanceId as string
  const historyId = params.historyId as string
  const { user, token, isLoading } = useAuth()
  const [browser, setBrowser] = useState<BrowserHistoryBrowserInfo | null>(null)
  const [history, setHistory] = useState<BrowserHistoryDetail | null>(null)
  const [folders, setFolders] = useState<Folder[]>([])
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  async function loadHistoryDetail() {
    if (!token) return

    setLoading(true)
    setError(null)

    try {
      const data = await api.getBrowserHistoryDetail(token, browserInstanceId, historyId)
      setBrowser(data.browser)
      setHistory(data.history as BrowserHistoryDetail)
      setFolders(data.folders || [])
      setBookmarks(data.bookmarks || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load history details')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
  }, [isLoading, user, router])

  useEffect(() => {
    if (token && browserInstanceId && historyId) {
      loadHistoryDetail()
    }
  }, [token, browserInstanceId, historyId])


  const formatDate = (timestamp: number | null | undefined) => {
    if (!timestamp) return 'N/A'
    const ms = timestamp < 1e12 ? timestamp * 1000 : timestamp
    return new Date(ms).toLocaleString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    })
  }

  const getBrowserIcon = (name: string) => {
    const lower = name.toLowerCase()
    if (lower.includes('chrome')) return '🌐'
    if (lower.includes('firefox')) return '🦊'
    if (lower.includes('edge')) return '📘'
    if (lower.includes('brave')) return '🦁'
    if (lower.includes('safari')) return '🧭'
    if (lower.includes('opera')) return '🎭'
    return '🔍'
  }

  const getTypeLabel = (type: string) => {
    switch (type) {
      case 'INITIAL_IMPORT':
        return 'Initial Import'
      case 'SYNC':
        return 'Sync'
      case 'MERGE_IMPORT':
        return 'Merge Import'
      default:
        return type
    }
  }

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'INITIAL_IMPORT':
        return 'bg-blue-100 dark:bg-blue-500/20 text-blue-700 dark:text-blue-400'
      case 'SYNC':
        return 'bg-slate-100 dark:bg-white/10 text-slate-700 dark:text-white/60'
      case 'MERGE_IMPORT':
        return 'bg-purple-100 dark:bg-purple-500/20 text-purple-700 dark:text-purple-400'
      default:
        return 'bg-slate-100 dark:bg-white/10 text-slate-700 dark:text-white/60'
    }
  }

  const getBreakdownRows = () => {
    const details = history?.details || {}
    const rows = [
      { label: 'Bookmarks created', value: details.bookmarksCreated ?? (history?.type === 'INITIAL_IMPORT' ? history.bookmarksProcessed : 0) },
      { label: 'Folders created', value: details.foldersCreated ?? (history?.type === 'INITIAL_IMPORT' ? history.foldersProcessed : 0) },
      { label: 'Bookmarks updated', value: details.bookmarksUpdated ?? 0 },
      { label: 'Folders updated', value: details.foldersUpdated ?? 0 },
      { label: 'Bookmarks deleted', value: details.bookmarksDeleted ?? 0 },
      { label: 'Folders deleted', value: details.foldersDeleted ?? 0 },
      { label: 'Bookmarks skipped', value: details.bookmarksSkipped ?? 0 },
      { label: 'Folders skipped', value: details.foldersSkipped ?? 0 },
    ]

    return rows.filter((row) => row.value > 0)
  }

  const buildHierarchy = () => {
    const folderMap = new Map<string, FolderNode>()

    const sortedFolders = [...folders].sort((a, b) => a.position - b.position)
    const sortedBookmarks = [...bookmarks].sort((a, b) => a.position - b.position)

    sortedFolders.forEach((folder) => {
      folderMap.set(folder.masterId, {
        ...folder,
        childFolders: [],
        childBookmarks: [],
      })
    })

    const rootFolders: FolderNode[] = []
    const rootBookmarks: Bookmark[] = []

    sortedFolders.forEach((folder) => {
      const node = folderMap.get(folder.masterId)
      if (!node) return

      const parent = folder.masterParentId ? folderMap.get(folder.masterParentId) : undefined
      if (parent) {
        parent.childFolders.push(node)
      } else {
        rootFolders.push(node)
      }
    })

    sortedBookmarks.forEach((bookmark) => {
      const parent = bookmark.masterParentId ? folderMap.get(bookmark.masterParentId) : undefined
      if (parent) {
        parent.childBookmarks.push(bookmark)
      } else {
        rootBookmarks.push(bookmark)
      }
    })

    const sortNodes = (nodes: FolderNode[]) => {
      nodes.sort((a, b) => a.position - b.position || a.title.localeCompare(b.title))
      nodes.forEach((node) => {
        node.childFolders.sort((a, b) => a.position - b.position || a.title.localeCompare(b.title))
        node.childBookmarks.sort((a, b) => a.position - b.position || a.title.localeCompare(b.title))
        sortNodes(node.childFolders)
      })
    }

    sortNodes(rootFolders)
    rootBookmarks.sort((a, b) => a.position - b.position || a.title.localeCompare(b.title))

    return { rootFolders, rootBookmarks }
  }

  const renderFolderNode = (node: FolderNode, depth = 0): ReactNode => {
    const indent = depth * 20

    return (
      <div key={node.id}>
        <div className="px-6 py-3 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors" style={{ paddingLeft: `${24 + indent}px` }}>
          <div className="flex items-center gap-3 min-w-0">
            <div className="w-9 h-9 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center text-lg shrink-0">📁</div>
            <div className="min-w-0">
              <div className="font-bold text-slate-700 dark:text-white/70 break-words">{node.title}</div>
              <div className="text-xs text-slate-400 dark:text-white/40 mt-1">Folder</div>
            </div>
          </div>
        </div>
        {node.childFolders.map((childFolder) => renderFolderNode(childFolder, depth + 1))}
        {node.childBookmarks.map((bookmark) => (
          <div key={bookmark.id} className="px-6 py-3 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors" style={{ paddingLeft: `${44 + indent}px` }}>
            <div className="flex items-center gap-3 min-w-0">
              <div className="w-9 h-9 rounded-xl bg-white dark:bg-[#242424] border border-slate-100 dark:border-white/5 flex items-center justify-center shadow-sm shrink-0">
                {bookmark.favicon ? (
                  <img src={bookmark.favicon} alt="" className="w-4 h-4 object-contain" />
                ) : (
                  <span className="text-lg">🔖</span>
                )}
              </div>
              <div className="min-w-0 flex-1">
                <div className="font-bold text-slate-700 dark:text-white/70 break-words">{bookmark.title}</div>
                <div className="text-xs text-slate-400 dark:text-white/40 truncate mt-1">{bookmark.url}</div>
              </div>
              <a
                href={bookmark.url}
                target="_blank"
                rel="noopener noreferrer"
                className="w-9 h-9 flex items-center justify-center rounded-xl text-slate-300 dark:text-white/30 hover:text-primary-600 dark:hover:text-terra-400 hover:bg-white dark:hover:bg-[#242424] hover:shadow-sm border border-transparent hover:border-slate-100 dark:hover:border-white/5 transition-all shrink-0"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                </svg>
              </a>
            </div>
          </div>
        ))}
      </div>
    )
  }

  const { rootFolders, rootBookmarks } = buildHierarchy()

  if (isLoading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  return (
    <DashboardLayout>
      <div className="max-w-6xl mx-auto">
        <Link
          href={`/settings/browsers/${browserInstanceId}/history`}
          className="inline-flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-cream-500 hover:text-primary-600 dark:hover:text-terra-400 transition-colors mb-6"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Back to Browser History
        </Link>

        {error ? (
          <div className="bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-2xl p-5 mb-8 flex items-center gap-3 text-red-700 dark:text-red-400">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className="font-medium">{error}</span>
          </div>
        ) : loading ? (
          <div className="p-16 text-center">
            <div className="w-10 h-10 border-3 border-primary-100 border-t-primary-600 rounded-full animate-spin mx-auto"></div>
            <p className="text-slate-500 dark:text-white/50 mt-6 font-medium">Loading history details...</p>
          </div>
        ) : history && browser ? (
          <>
            <div className="mb-10 flex items-start gap-4">
              <div className="w-14 h-14 bg-slate-50 dark:bg-white/5 rounded-2xl flex items-center justify-center text-3xl">
                {getBrowserIcon(browser.browser)}
              </div>
              <div>
                <h1 className="text-3xl font-bold text-slate-900 dark:text-cream-100">
                  {browser.nickname || browser.browser} Import Details
                </h1>
                <p className="text-slate-600 dark:text-cream-500 mt-2 text-lg">
                  Full list of folders and bookmarks recorded for this history entry
                </p>
              </div>
            </div>

            <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] p-8 shadow-sm mb-8">
              <div className="flex flex-wrap items-center gap-3 mb-6">
                <span className={`px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${getTypeColor(history.type)}`}>
                  {getTypeLabel(history.type)}
                </span>
                <span className="inline-flex items-center gap-1.5 text-sm text-slate-500 dark:text-white/50">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7h16M4 12h16M4 17h10" />
                  </svg>
                  {history.collectionName}
                </span>
                <span className="text-sm text-slate-500 dark:text-white/50">
                  {formatDate(history.timestamp || history.createdAt)}
                </span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
                <div className="rounded-2xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] p-5">
                  <div className="text-2xl font-bold text-slate-900 dark:text-cream-100">{history.changesCount}</div>
                  <div className="text-sm text-slate-500 dark:text-white/50 mt-1">Total Changes</div>
                </div>
                <div className="rounded-2xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] p-5">
                  <div className="text-2xl font-bold text-slate-900 dark:text-cream-100">{bookmarks.length}</div>
                  <div className="text-sm text-slate-500 dark:text-white/50 mt-1">Bookmarks Listed</div>
                </div>
                <div className="rounded-2xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] p-5">
                  <div className="text-2xl font-bold text-slate-900 dark:text-cream-100">{folders.length}</div>
                  <div className="text-sm text-slate-500 dark:text-white/50 mt-1">Folders Listed</div>
                </div>
              </div>

              <div className="rounded-2xl border border-slate-200 dark:border-white/10 bg-slate-50 dark:bg-white/5 p-4">
                <div className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-white/40 mb-3">
                  Change Breakdown
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                  {getBreakdownRows().map((row) => (
                    <div
                      key={row.label}
                      className="rounded-xl bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/[0.06] px-4 py-3"
                    >
                      <div className="text-lg font-bold text-slate-900 dark:text-cream-100">
                        {row.value}
                      </div>
                      <div className="text-xs text-slate-500 dark:text-white/50 mt-1">
                        {row.label}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm">
              <div className="px-8 py-6 border-b border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5 flex items-center justify-between">
                <h2 className="font-bold text-slate-900 dark:text-cream-100">Imported Hierarchy</h2>
                <span className="text-xs text-slate-400 dark:text-white/40">{folders.length + bookmarks.length} items</span>
              </div>
              <div className="max-h-[700px] overflow-y-auto custom-scrollbar divide-y divide-slate-100 dark:divide-white/5">
                {rootFolders.length === 0 && rootBookmarks.length === 0 ? (
                  <div className="p-10 text-center text-slate-500 dark:text-white/50">No items recorded for this entry.</div>
                ) : (
                  <>
                    {rootFolders.map((folder) => renderFolderNode(folder))}
                    {rootBookmarks.map((bookmark) => (
                      <div key={bookmark.id} className="px-6 py-3 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors">
                        <div className="flex items-center gap-3 min-w-0">
                          <div className="w-9 h-9 rounded-xl bg-white dark:bg-[#242424] border border-slate-100 dark:border-white/5 flex items-center justify-center shadow-sm shrink-0">
                            {bookmark.favicon ? (
                              <img src={bookmark.favicon} alt="" className="w-4 h-4 object-contain" />
                            ) : (
                              <span className="text-lg">🔖</span>
                            )}
                          </div>
                          <div className="min-w-0 flex-1">
                            <div className="font-bold text-slate-700 dark:text-white/70 break-words">{bookmark.title}</div>
                            <div className="text-xs text-slate-400 dark:text-white/40 truncate mt-1">{bookmark.url}</div>
                          </div>
                          <a
                            href={bookmark.url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="w-9 h-9 flex items-center justify-center rounded-xl text-slate-300 dark:text-white/30 hover:text-primary-600 dark:hover:text-terra-400 hover:bg-white dark:hover:bg-[#242424] hover:shadow-sm border border-transparent hover:border-slate-100 dark:hover:border-white/5 transition-all shrink-0"
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                            </svg>
                          </a>
                        </div>
                      </div>
                    ))}
                  </>
                )}
              </div>
            </div>
          </>
        ) : null}
      </div>
    </DashboardLayout>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter, useParams } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import DashboardLayout from '@/components/DashboardLayout'

interface SyncDetails {
    changesProcessed?: number
    bookmarksCreated?: number
    foldersCreated?: number
    bookmarksUpdated?: number
    foldersUpdated?: number
    bookmarksDeleted?: number
    foldersDeleted?: number
    bookmarksSkipped?: number
    foldersSkipped?: number
}

interface SyncHistory {
    id: number
    browserInstanceId: string
    type: 'INITIAL_IMPORT' | 'SYNC' | 'MERGE_IMPORT'
    changesCount: number
    status: 'SUCCESS' | 'FAILED' | 'PARTIAL'
    bookmarksProcessed: number
    foldersProcessed: number
    collectionName: string
    sessionId: string | null
    timestamp: number
    createdAt: number
    details: SyncDetails | null
}

interface BrowserInfo {
    browserInstanceId: string
    browser: string
    browserVersion: string
    nickname: string | null
    os: string | null
}

export default function BrowserHistoryPage() {
    const router = useRouter()
    const params = useParams()
    const browserInstanceId = params.browserInstanceId as string
    const { user, token, isLoading } = useAuth()
    const [history, setHistory] = useState<SyncHistory[]>([])
    const [browserInfo, setBrowserInfo] = useState<BrowserInfo | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)

      async function fetchHistory() {
        if (!token) return

        setLoading(true)
        setError(null)

        try {
            const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005'
            const response = await fetch(`${API_URL}/api/v1/user/browsers/${browserInstanceId}/history`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                },
            })

            const data = await response.json()

            if (data.success) {
                setHistory(data.data.history || [])
                setBrowserInfo(data.data.browser || null)
            } else {
                setError(data.error?.message || 'Failed to fetch history')
            }
        } catch (err) {
            setError('Failed to connect to server')
            console.error('Failed to fetch history:', err)
        } finally {
            setLoading(false)
        }
    }

  useEffect(() => {
        if (!isLoading && !user) {
            router.push('/login')
        }
    }, [isLoading, user, router])

    useEffect(() => {
        if (token && browserInstanceId) {
            fetchHistory()
        }
    }, [token, browserInstanceId])


    const formatDate = (timestamp: number | null) => {
        if (!timestamp) return 'N/A'
        const ms = timestamp < 1e12 ? timestamp * 1000 : timestamp
        return new Date(ms).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        })
    }

    const getTypeLabel = (type: string) => {
        switch (type) {
            case 'INITIAL_IMPORT': return 'Initial Import'
            case 'SYNC': return 'Sync'
            case 'MERGE_IMPORT': return 'Merge Import'
            default: return type
        }
    }

    const getTypeColor = (type: string) => {
        switch (type) {
            case 'INITIAL_IMPORT': return 'bg-blue-100 dark:bg-blue-500/20 text-blue-700 dark:text-blue-400'
            case 'SYNC': return 'bg-slate-100 dark:bg-white/10 text-slate-700 dark:text-white/60'
            case 'MERGE_IMPORT': return 'bg-purple-100 dark:bg-purple-500/20 text-purple-700 dark:text-purple-400'
            default: return 'bg-slate-100 dark:bg-white/10 text-slate-700 dark:text-white/60'
        }
    }

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'SUCCESS': return 'text-green-600 dark:text-green-400'
            case 'FAILED': return 'text-red-600 dark:text-red-400'
            case 'PARTIAL': return 'text-amber-600 dark:text-amber-400'
            default: return 'text-slate-600 dark:text-white/60'
        }
    }

    const getBrowserIcon = (browser: string) => {
        const lower = browser.toLowerCase()
        if (lower.includes('chrome')) return '🌐'
        if (lower.includes('firefox')) return '🦊'
        if (lower.includes('edge')) return '📘'
        if (lower.includes('brave')) return '🦁'
        if (lower.includes('safari')) return '🧭'
        if (lower.includes('opera')) return '🎭'
        return '🔍'
    }

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
            </div>
        )
    }

    return (
        <DashboardLayout>
            <div className="max-w-6xl mx-auto">
                {/* Back Link */}
                <Link
                    href="/settings/browsers"
                    className="inline-flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-cream-500 hover:text-primary-600 dark:hover:text-terra-400 transition-colors mb-6"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                    </svg>
                    Back to Browsers
                </Link>

                {/* Header */}
                <div className="mb-10">
                    <div className="flex items-center gap-4">
                        {browserInfo && (
                            <div className="w-14 h-14 bg-slate-50 dark:bg-white/5 rounded-2xl flex items-center justify-center text-3xl">
                                {getBrowserIcon(browserInfo.browser)}
                            </div>
                        )}
                        <div>
                            <h1 className="text-3xl font-bold text-slate-900 dark:text-cream-100">
                                {browserInfo?.nickname || browserInfo?.browser || 'Browser'} History
                            </h1>
                            {browserInfo?.nickname && (
                                <p className="text-slate-500 dark:text-white/50 mt-1">
                                    {browserInfo.browser} v{browserInfo.browserVersion} • {browserInfo.os || 'Unknown OS'}
                                </p>
                            )}
                        </div>
                    </div>
                    <p className="text-slate-600 dark:text-cream-500 mt-2 text-lg">
                        Sync activity and import history for this browser
                    </p>
                </div>

                {/* Error Message */}
                {error && (
                    <div className="bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-2xl p-5 mb-8 flex items-center gap-3 text-red-700 dark:text-red-400">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        <span className="font-medium">{error}</span>
                    </div>
                )}

                {/* History List */}
                <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm">
                    <div className="px-8 py-6 border-b border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5">
                        <h2 className="font-bold text-slate-900 dark:text-cream-100">Sync History</h2>
                    </div>

                    {loading ? (
                        <div className="p-16 text-center">
                            <div className="w-10 h-10 border-3 border-primary-100 border-t-primary-600 rounded-full animate-spin mx-auto"></div>
                            <p className="text-slate-500 dark:text-white/50 mt-6 font-medium">Loading history...</p>
                        </div>
                    ) : history.length === 0 ? (
                        <div className="p-20 text-center">
                            <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
                                <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                            </div>
                            <h3 className="text-xl font-bold text-slate-900 dark:text-cream-100 mb-2">No history yet</h3>
                            <p className="text-slate-500 dark:text-white/50 max-w-xs mx-auto text-lg">
                                This browser hasn&apos;t performed any sync operations yet.
                            </p>
                        </div>
                    ) : (
                        <div className="divide-y divide-slate-100 dark:divide-white/5">
                            {history.map((item) => (
                                <div
                                    key={item.id}
                                    className="px-8 py-5 hover:bg-slate-50 dark:hover:bg-white/5 transition-all"
                                >
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-4">
                                            <span className={`px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${getTypeColor(item.type)}`}>
                                                {getTypeLabel(item.type)}
                                            </span>
                                            <div className="flex items-center gap-4 text-sm text-slate-500 dark:text-white/50">
                                                <span className="flex items-center gap-1.5">
                                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                                                    </svg>
                                                    {item.bookmarksProcessed} bookmarks
                                                </span>
                                                <span className="flex items-center gap-1.5">
                                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" />
                                                    </svg>
                                                    {item.foldersProcessed} folders
                                                </span>
                                                <span className="flex items-center gap-1.5">
                                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7h16M4 12h16M4 17h10" />
                                                    </svg>
                                                    {item.collectionName}
                                                </span>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-6">
                                            <span className={`font-bold text-sm ${getStatusColor(item.status)}`}>
                                                {item.status}
                                            </span>
                                            <span className="text-xs text-slate-400 dark:text-white/40">
                                                {formatDate(item.timestamp || item.createdAt)}
                                            </span>
                                        </div>
                                    </div>
                                    {item.changesCount > 0 && (
                                        <div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-slate-400 dark:text-white/40">
                                            {item.sessionId ? (
                                                <Link
                                                    href={`/settings/browsers/${browserInstanceId}/history/${item.id}`}
                                                    className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 dark:border-white/10 px-2.5 py-1.5 text-xs font-semibold text-slate-600 dark:text-white/60 hover:bg-slate-100 dark:hover:bg-white/10 transition-all"
                                                >
                                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                                                    </svg>
                                                    {item.details?.changesProcessed ?? item.changesCount} changes processed
                                                </Link>
                                            ) : (
                                                <span className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 dark:border-white/10 px-2.5 py-1.5 text-xs font-semibold text-slate-400 dark:text-white/40">
                                                    {item.details?.changesProcessed ?? item.changesCount} changes processed
                                                </span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Summary Stats */}
                {history.length > 0 && (
                    <div className="mt-8 grid grid-cols-1 sm:grid-cols-3 gap-4">
                        <div className="bg-white dark:bg-[#242424] rounded-2xl border border-slate-200 dark:border-white/[0.06] p-6">
                            <div className="text-2xl font-bold text-slate-900 dark:text-cream-100">
                                {history.length}
                            </div>
                            <div className="text-sm text-slate-500 dark:text-white/50 mt-1">Total Syncs</div>
                        </div>
                        <div className="bg-white dark:bg-[#242424] rounded-2xl border border-slate-200 dark:border-white/[0.06] p-6">
                            <div className="text-2xl font-bold text-slate-900 dark:text-cream-100">
                                {history.reduce((sum, h) => sum + h.bookmarksProcessed, 0).toLocaleString()}
                            </div>
                            <div className="text-sm text-slate-500 dark:text-white/50 mt-1">Bookmarks Processed</div>
                        </div>
                        <div className="bg-white dark:bg-[#242424] rounded-2xl border border-slate-200 dark:border-white/[0.06] p-6">
                            <div className="text-2xl font-bold text-slate-900 dark:text-cream-100">
                                {history.reduce((sum, h) => sum + h.foldersProcessed, 0).toLocaleString()}
                            </div>
                            <div className="text-sm text-slate-500 dark:text-white/50 mt-1">Folders Processed</div>
                        </div>
                    </div>
                )}
            </div>
        </DashboardLayout>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import DashboardLayout from '@/components/DashboardLayout'
import ConfirmDialog from '@/components/ConfirmDialog'

interface Browser {
    browserInstanceId: string
    browser: string
    browserVersion: string
    os: string | null
    osVersion: string | null
    nickname: string | null
    lastSeen: number
    createdAt: number
}

export default function BrowsersPage() {
    const router = useRouter()
    const { user, token, isLoading } = useAuth()
    const [browsers, setBrowsers] = useState<Browser[]>([])
    const [loadingBrowsers, setLoadingBrowsers] = useState(true)
    const [deletingId, setDeletingId] = useState<string | null>(null)
    const [recentCutoff] = useState(() => Date.now() - 60 * 60 * 1000)
    const [error, setError] = useState<string | null>(null)
    const [editingNicknameId, setEditingNicknameId] = useState<string | null>(null)
    const [nicknameInput, setNicknameInput] = useState<string>('')
    const [savingNickname, setSavingNickname] = useState(false)
    const [confirmDialog, setConfirmDialog] = useState<{ isOpen: boolean; browserInstanceId: string | null }>({ isOpen: false, browserInstanceId: null })

      async function fetchBrowsers() {
        if (!token) return

        setLoadingBrowsers(true)
        setError(null)

        try {
            const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005'
            const response = await fetch(`${API_URL}/api/v1/user/browsers`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                },
            })

            const data = await response.json()

            if (data.success) {
                setBrowsers(data.data || [])
            } else {
                setError(data.error?.message || 'Failed to fetch browsers')
            }
        } catch (err) {
            setError('Failed to connect to server')
            console.error('Failed to fetch browsers:', err)
        } finally {
            setLoadingBrowsers(false)
        }
    }

  useEffect(() => {
        if (!isLoading && !user) {
            router.push('/login')
        }
    }, [isLoading, user, router])

    useEffect(() => {
        if (token) {
            fetchBrowsers()
        }
    }, [token])


    const handleUpdateNickname = async (browserInstanceId: string) => {
        if (!token) return

        setSavingNickname(true)
        setError(null)

        try {
            const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005'
            const response = await fetch(`${API_URL}/api/v1/user/browsers/${browserInstanceId}`, {
                method: 'PATCH',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ nickname: nicknameInput || null }),
            })

            const data = await response.json()

            if (data.success) {
                setBrowsers(browsers.map(b => 
                    b.browserInstanceId === browserInstanceId 
                        ? { ...b, nickname: nicknameInput || null }
                        : b
                ))
                setEditingNicknameId(null)
                setNicknameInput('')
            } else {
                setError(data.error?.message || 'Failed to update nickname')
            }
        } catch (err) {
            setError('Failed to connect to server')
            console.error('Failed to update nickname:', err)
        } finally {
            setSavingNickname(false)
        }
    }

    const startEditingNickname = (browser: Browser) => {
        setEditingNicknameId(browser.browserInstanceId)
        setNicknameInput(browser.nickname || '')
    }

    const cancelEditingNickname = () => {
        setEditingNicknameId(null)
        setNicknameInput('')
    }

    const handleRemoveBrowser = (browserInstanceId: string) => {
        if (!token) return
        setConfirmDialog({ isOpen: true, browserInstanceId })
    }

    const executeRemoveBrowser = async () => {
        const browserInstanceId = confirmDialog.browserInstanceId
        if (!token || !browserInstanceId) return
        setConfirmDialog({ isOpen: false, browserInstanceId: null })

        setDeletingId(browserInstanceId)
        setError(null)

        try {
            const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005'
            const response = await fetch(`${API_URL}/api/v1/user/browsers/${browserInstanceId}`, {
                method: 'DELETE',
                headers: {
                    'Authorization': `Bearer ${token}`,
                },
            })

            const data = await response.json()

            if (data.success) {
                setBrowsers(browsers.filter(b => b.browserInstanceId !== browserInstanceId))
            } else {
                setError(data.error?.message || 'Failed to remove browser')
            }
        } catch (err) {
            setError('Failed to connect to server')
            console.error('Failed to remove browser:', err)
        } finally {
            setDeletingId(null)
        }
    }

    const formatDate = (timestamp: number | null) => {
        if (!timestamp) return 'Never'
        // Handle both seconds and milliseconds timestamps
        const ms = timestamp < 1e12 ? timestamp * 1000 : timestamp
        return new Date(ms).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        })
    }

    const getBrowserIcon = (browser: string) => {
        const lower = browser.toLowerCase()
        if (lower.includes('chrome')) return '🌐'
        if (lower.includes('firefox')) return '🦊'
        if (lower.includes('edge')) return '📘'
        if (lower.includes('brave')) return '🦁'
        if (lower.includes('safari')) return '🧭'
        if (lower.includes('opera')) return '🎭'
        return '🔍'
    }

    const getOSIcon = (os: string | null) => {
        if (!os) return '💻'
        const lower = os.toLowerCase()
        if (lower.includes('windows')) return '🪟'
        if (lower.includes('mac')) return '🍎'
        if (lower.includes('linux')) return '🐧'
        if (lower.includes('android')) return '🤖'
        if (lower.includes('ios')) return '📱'
        return '💻'
    }

    const isRecent = (timestamp: number | null) => {
        if (!timestamp) return false
        const ms = timestamp < 1e12 ? timestamp * 1000 : timestamp
        const hourAgo = recentCutoff
        return ms > hourAgo
    }

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
            </div>
        )
    }

    return (
        <DashboardLayout>
            <div className="max-w-6xl mx-auto">
                {/* Header */}
                <div className="mb-10">
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-cream-100">Manage Browsers</h1>
                    <p className="text-slate-600 dark:text-cream-500 mt-2 text-lg">
                        View and manage browser instances connected to your account
                    </p>
                </div>

                {/* Usage Info */}
                <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] p-8 mb-8 shadow-sm">
                    <div className="flex flex-col sm:flex-row items-center justify-between gap-6">
                        <div>
                            <h2 className="text-xl font-bold text-slate-900 dark:text-cream-100">Browser Slots</h2>
                            <p className="text-slate-500 dark:text-white/50 mt-2 font-medium">
                                {user.subscriptionTier === 'premium'
                                    ? 'You have unlimited browser connections'
                                    : `Free plan usage: ${browsers.length} of ${user.browserLimit} slots used`
                                }
                            </p>
                        </div>
                        <div className="flex items-center gap-6">
                            <div className="text-right">
                                <div className="text-4xl font-black text-slate-900 dark:text-cream-100 tracking-tight">
                                    {browsers.length} / {user.browserLimit >= 100 ? '∞' : user.browserLimit}
                                </div>
                                <div className="text-xs text-slate-400 dark:text-white/40 font-bold uppercase tracking-widest mt-1">Active Slots</div>
                            </div>
                        </div>
                    </div>

                    {user.subscriptionTier !== 'premium' && browsers.length >= user.browserLimit && (
                        <div className="mt-8 relative overflow-hidden bg-primary-50 dark:bg-terra-500/10 rounded-2xl p-6 border border-primary-100 dark:border-terra-500/20">
                            <div className="relative z-10 flex items-start gap-4">
                                <div className="w-10 h-10 bg-white dark:bg-[#242424] rounded-xl flex items-center justify-center shadow-sm">
                                    <svg className="w-6 h-6 text-primary-600 dark:text-terra-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                    </svg>
                                </div>
                                <div>
                                    <h3 className="font-bold text-primary-900 dark:text-terra-300">Browser limit reached</h3>
                                    <p className="text-primary-700/80 dark:text-terra-300/80 mt-1 text-sm leading-relaxed">
                                        You&apos;ve utilized all available browser slots. To add a new browser, please remove an existing connection or
                                        <Link href="/settings/subscription" className="text-primary-600 dark:text-terra-400 hover:text-primary-700 dark:hover:text-terra-300 font-bold underline decoration-2 underline-offset-4 ml-1">
                                            upgrade to Premium
                                        </Link> for unlimited connections.
                                    </p>
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Error Message */}
                {error && (
                    <div className="bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-2xl p-5 mb-8 flex items-center gap-3 text-red-700 dark:text-red-400 animate-in slide-in-from-top-4">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        <span className="font-medium">{error}</span>
                    </div>
                )}

                {/* Browser List */}
                <div className="bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] overflow-hidden shadow-sm">
                    <div className="px-8 py-6 border-b border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5">
                        <h2 className="font-bold text-slate-900 dark:text-cream-100">Connected Devices</h2>
                    </div>

                    {loadingBrowsers ? (
                        <div className="p-16 text-center">
                            <div className="w-10 h-10 border-3 border-primary-100 border-t-primary-600 rounded-full animate-spin mx-auto"></div>
                            <p className="text-slate-500 dark:text-white/50 mt-6 font-medium">Scanning connections...</p>
                        </div>
                    ) : browsers.length === 0 ? (
                        <div className="p-20 text-center">
                            <div className="w-20 h-20 bg-slate-50 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
                                <svg className="w-10 h-10 text-slate-300 dark:text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9" />
                                </svg>
                            </div>
                            <h3 className="text-xl font-bold text-slate-900 dark:text-cream-100 mb-2">No browsers connected</h3>
                            <p className="text-slate-500 dark:text-white/50 max-w-xs mx-auto text-lg">
                                Install the extension and run an initial sync to connect your first browser.
                            </p>
                        </div>
                    ) : (
                        <div className="divide-y divide-slate-100 dark:divide-white/5">
                            {browsers.map((browser) => (
                                <div
                                    key={browser.browserInstanceId}
                                    className="px-8 py-6 flex items-center justify-between hover:bg-slate-50 dark:hover:bg-white/5 transition-all group"
                                >
                                    <div className="flex items-center gap-6">
                                        <div className="w-16 h-16 bg-slate-50 dark:bg-white/5 rounded-2xl flex items-center justify-center group-hover:bg-white dark:group-hover:bg-[#242424] group-hover:shadow-md transition-all text-4xl">
                                            {getBrowserIcon(browser.browser)}
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-3">
                                                <span className="text-lg font-bold text-slate-900 dark:text-cream-100">
                                                    {browser.nickname || browser.browser}
                                                </span>
                                                {browser.nickname && (
                                                    <span className="bg-primary-100 dark:bg-terra-500/20 text-primary-600 dark:text-terra-400 text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-lg">
                                                        {browser.browser}
                                                    </span>
                                                )}
                                                <span className="bg-slate-100 dark:bg-white/10 text-slate-500 dark:text-white/50 text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-lg">
                                                    v{browser.browserVersion}
                                                </span>
                                                {isRecent(browser.lastSeen) && (
                                                    <div className="flex items-center gap-1.5 ml-1">
                                                        <span className="relative flex h-2 w-2">
                                                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                                                            <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
                                                        </span>
                                                        <span className="text-green-600 dark:text-green-400 text-xs font-bold uppercase tracking-tight">Online</span>
                                                    </div>
                                                )}
                                            </div>
                                            <div className="flex items-center gap-3 text-sm text-slate-500 dark:text-white/50 mt-1.5 font-medium">
                                                <span className="flex items-center gap-1.5 bg-slate-100 dark:bg-white/10 px-2 py-0.5 rounded-md text-xs font-bold uppercase tracking-tighter">
                                                    {getOSIcon(browser.os)} {browser.os || 'Unknown OS'}
                                                </span>
                                                {browser.osVersion && (
                                                    <span className="text-slate-400 dark:text-white/40 italic font-normal">({browser.osVersion})</span>
                                                )}
                                            </div>
                                            <div className="text-xs text-slate-400 dark:text-white/40 mt-2 font-medium">
                                                Last Active: {formatDate(browser.lastSeen)}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-3">
                                        {editingNicknameId === browser.browserInstanceId ? (
                                            <div className="flex items-center gap-2">
                                                <input
                                                    type="text"
                                                    value={nicknameInput}
                                                    onChange={(e) => setNicknameInput(e.target.value)}
                                                    placeholder="Enter nickname..."
                                                    maxLength={50}
                                                    className="h-10 px-3 rounded-xl text-sm bg-white dark:bg-[#242424] border border-slate-200 dark:border-white/10 focus:border-primary-500 dark:focus:border-terra-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 dark:focus:ring-terra-500/20 transition-all w-40"
                                                    onKeyDown={(e) => {
                                                        if (e.key === 'Enter') {
                                                            handleUpdateNickname(browser.browserInstanceId)
                                                        } else if (e.key === 'Escape') {
                                                            cancelEditingNickname()
                                                        }
                                                    }}
                                                    autoFocus
                                                />
                                                <button
                                                    onClick={() => handleUpdateNickname(browser.browserInstanceId)}
                                                    disabled={savingNickname}
                                                    className="h-10 px-3 rounded-xl text-sm font-bold text-white bg-primary-600 dark:bg-terra-500 hover:bg-primary-700 dark:hover:bg-terra-600 transition-all disabled:opacity-50"
                                                >
                                                    {savingNickname ? (
                                                        <svg className="animate-spin h-4 w-4" fill="none" viewBox="0 0 24 24">
                                                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                                        </svg>
                                                    ) : (
                                                        'Save'
                                                    )}
                                                </button>
                                                <button
                                                    onClick={cancelEditingNickname}
                                                    disabled={savingNickname}
                                                    className="h-10 px-3 rounded-xl text-sm font-bold text-slate-600 dark:text-white/60 hover:bg-slate-100 dark:hover:bg-white/10 transition-all disabled:opacity-50"
                                                >
                                                    Cancel
                                                </button>
                                            </div>
                                        ) : (
                                            <>
                                                <Link
                                                    href={`/settings/browsers/${browser.browserInstanceId}/history`}
                                                    className="h-10 px-4 rounded-xl text-sm font-bold text-primary-600 dark:text-terra-400 hover:bg-primary-50 dark:hover:bg-terra-500/10 border border-transparent hover:border-primary-200 dark:hover:border-terra-500/20 transition-all flex items-center"
                                                >
                                                    <svg className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                                                    </svg>
                                                    History
                                                </Link>
                                                <button
                                                    onClick={() => startEditingNickname(browser)}
                                                    className="h-10 px-4 rounded-xl text-sm font-bold text-slate-600 dark:text-white/60 hover:bg-slate-100 dark:hover:bg-white/10 border border-transparent hover:border-slate-200 dark:hover:border-white/10 transition-all"
                                                >
                                                    {browser.nickname ? 'Edit Name' : 'Add Name'}
                                                </button>
                                                <button
                                                    onClick={() => handleRemoveBrowser(browser.browserInstanceId)}
                                                    disabled={deletingId === browser.browserInstanceId}
                                                    className="h-10 px-4 rounded-xl text-sm font-bold text-red-600 hover:bg-red-50 dark:hover:bg-red-500/10 border border-transparent hover:border-red-100 dark:hover:border-red-500/20 transition-all disabled:opacity-50"
                                                >
                                                    {deletingId === browser.browserInstanceId ? (
                                                        <span className="flex items-center gap-2">
                                                            <svg className="animate-spin h-4 w-4 text-red-600" fill="none" viewBox="0 0 24 24">
                                                                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                                                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                                            </svg>
                                                            Removing...
                                                        </span>
                                                    ) : (
                                                        'Disconnect'
                                                    )}
                                                </button>
                                            </>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Help Text */}
                <div className="mt-10 relative overflow-hidden bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/[0.06] rounded-3xl p-8">
                    <div className="relative z-10 flex gap-6">
                        <div className="w-12 h-12 rounded-2xl bg-white dark:bg-[#242424] flex items-center justify-center shrink-0 shadow-sm">
                            <svg className="w-6 h-6 text-slate-400 dark:text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-slate-900 dark:text-cream-100 mb-4">How browser connections work</h3>
                            <ul className="text-slate-600 dark:text-cream-500 space-y-3 font-medium">
                                <li className="flex items-start gap-2.5">
                                    <span className="w-1.5 h-1.5 rounded-full bg-primary-600 dark:bg-terra-500 mt-2 shrink-0"></span>
                                    Each browser instance counts as one unique connection to your Master Collection.
                                </li>
                                <li className="flex items-start gap-2.5">
                                    <span className="w-1.5 h-1.5 rounded-full bg-primary-600 dark:bg-terra-500 mt-2 shrink-0"></span>
                                    Different profiles in the same browser (e.g., Work vs Personal) are treated as separate connections.
                                </li>
                                <li className="flex items-start gap-2.5">
                                    <span className="w-1.5 h-1.5 rounded-full bg-primary-600 dark:bg-terra-500 mt-2 shrink-0"></span>
                                    Disconnecting a browser stops syncing. Your bookmarks in the Master Collection are preserved.
                                </li>
                                <li className="flex items-start gap-2.5">
                                    <span className="w-1.5 h-1.5 rounded-full bg-primary-600 dark:bg-terra-500 mt-2 shrink-0"></span>
                                    To reconnect a removed browser, you&apos;ll need to run a fresh initial sync from the extension.
                                </li>
                            </ul>
                        </div>
                    </div>
                </div>
            </div>

            <ConfirmDialog
                isOpen={confirmDialog.isOpen}
                title="Disconnect Browser"
                message="Are you sure you want to remove this browser?\n\nIt will need to run an initial sync again to reconnect."
                confirmText="Disconnect"
                cancelText="Cancel"
                variant="danger"
                onConfirm={executeRemoveBrowser}
                onCancel={() => setConfirmDialog({ isOpen: false, browserInstanceId: null })}
            />
        </DashboardLayout>
    )
}

'use client'

import { useEffect, useState, useRef } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useAuth } from '@/lib/auth-context'
import { api } from '@/lib/api'
import DashboardLayout from '@/components/DashboardLayout'
import AlertDialog from '@/components/AlertDialog'

export default function SubscriptionPage() {
  const router = useRouter()
  const { user, token, isLoading, isPremium, refreshUser } = useAuth()

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login')
    }
  }, [isLoading, user, router])

  const [checkoutLoading, setCheckoutLoading] = useState<string | null>(null)
  const [paymentPending, setPaymentPending] = useState(false)
  const [paymentError, setPaymentError] = useState<string | null>(null)
  const returnHandled = useRef(false)
  const [alertDialog, setAlertDialog] = useState<{ isOpen: boolean; title: string; message: string; variant: 'success' | 'error' }>({ isOpen: false, title: '', message: '', variant: 'error' })

  const confirmReturn = async () => {
    if (!token) return
    const params = new URLSearchParams(window.location.search)
    const orderID = params.get('token')
    const subscriptionID = params.get('subscription_id')
    setPaymentPending(true)
    setPaymentError(null)
    try {
      if (params.get('plan') === 'lifetime' && orderID) await api.capturePayment(token, orderID)
      else if (subscriptionID) await api.confirmSubscription(token, subscriptionID)
      else throw new Error('Payment confirmation details are missing. Contact support before making another payment.')
      await refreshUser()
      router.replace('/settings/subscription')
    } catch (error) {
      setPaymentError(error instanceof Error ? error.message : 'Payment confirmation is pending. Please retry.')
    } finally { setPaymentPending(false) }
  }

  useEffect(() => {
    if (token && new URLSearchParams(window.location.search).get('success') === 'true' && !returnHandled.current) {
      returnHandled.current = true
      void confirmReturn()
    }
  }, [token])

  const handleUpgrade = async (plan: 'monthly' | 'yearly' | 'lifetime') => {
    if (!token) return
    setCheckoutLoading(plan)
    try {
      const result = await api.createCheckout(token, plan)
      window.location.assign(result.checkoutUrl)
    } catch (err) {
      console.error('Failed to create checkout:', err)
      setAlertDialog({
        isOpen: true,
        title: 'Checkout Failed',
        message: 'Failed to start checkout. Please try again.',
        variant: 'error'
      })
    } finally {
      setCheckoutLoading(null)
    }
  }

  const handleManageSubscription = () => {
    // PayPal doesn't offer a customer portal — users manage subscriptions from their PayPal account
    window.open('https://www.paypal.com/myaccount/autopay/', '_blank')
  }

  const formatDate = (timestamp: number | null) => {
    if (!timestamp) return 'Never'
    return new Date(timestamp * 1000).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })
  }

  if (isLoading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500"></div>
      </div>
    )
  }

  return (
    <DashboardLayout>
      <div className="max-w-6xl mx-auto">
        {paymentPending && <p role="status" className="mb-6">Confirming your payment…</p>}
        {paymentError && <div role="alert" className="mb-6 rounded-xl border border-red-300 p-4">
          <p>{paymentError}</p>
          <button type="button" disabled={paymentPending} onClick={() => void confirmReturn()} className="mt-3 underline">Retry confirmation</button>
        </div>}
        {/* Header */}
        <div className="mb-10 text-center md:text-left">
          <h1 className="text-3xl font-bold text-slate-900 dark:text-cream-100">Subscription</h1>
          <p className="text-slate-600 dark:text-cream-500 mt-2 text-lg">Manage your account tier and billing</p>
        </div>

        {/* Current Plan Card */}
        <div className={`relative overflow-hidden rounded-[2.5rem] border p-10 mb-12 shadow-xl ${isPremium
          ? 'bg-gradient-to-br from-primary-600 to-primary-700 border-primary-500 text-white shadow-primary-500/20'
          : 'bg-white dark:bg-[#242424] border-slate-200 dark:border-white/[0.06] shadow-slate-200/50 dark:shadow-none'
          }`}>
          <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
            <div className="flex items-center gap-6">
              <div className={`w-20 h-20 rounded-3xl flex items-center justify-center text-4xl shadow-inner ${isPremium ? 'bg-white/10' : 'bg-slate-50 dark:bg-white/5'
                }`}>
                {isPremium ? '💎' : '🌱'}
              </div>
              <div className="text-center md:text-left">
                <div className={`text-sm font-black uppercase tracking-[0.2em] mb-1 ${isPremium ? 'text-white/60' : 'text-slate-400 dark:text-white/40'}`}>
                  Current Status
                </div>
                <h2 className={`text-3xl font-black antialiased ${isPremium ? 'text-white' : 'text-slate-900 dark:text-cream-100'}`}>
                  {isPremium ? 'Premium' : 'Free'}
                </h2>
                {isPremium && (
                  <div className="mt-2 inline-flex items-center gap-2 bg-white/10 px-3 py-1 rounded-full text-xs font-bold text-white/90">
                    <span className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></span>
                    {user.subscriptionExpiresAt
                      ? `Active until ${formatDate(user.subscriptionExpiresAt)}`
                      : 'Lifetime Access Activated'}
                  </div>
                )}
              </div>
            </div>
            {isPremium && (
              <button
                onClick={handleManageSubscription}
                className="bg-white dark:bg-cream-100 text-primary-600 dark:text-terra-400 hover:bg-slate-50 dark:hover:bg-white px-8 py-3.5 rounded-2xl font-bold transition-all shadow-lg active:scale-95"
              >
                Billing Portal
              </button>
            )}
          </div>

          {!isPremium && (
            <div className="mt-10 grid grid-cols-3 gap-6 pt-10 border-t border-slate-100 dark:border-white/5">
              <div className="text-center">
                <div className="text-2xl font-black text-slate-900 dark:text-cream-100">{user.bookmarkLimit.toLocaleString()}</div>
                <div className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-white/40 mt-1">Bookmarks</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-black text-slate-900 dark:text-cream-100">{user.browserLimit}</div>
                <div className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-white/40 mt-1">Browsers</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-black text-slate-900 dark:text-cream-100">{user.collectionLimit}</div>
                <div className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-white/40 mt-1">Collections</div>
              </div>
            </div>
          )}

          {/* Decorative blobs for premium card */}
          {isPremium && (
            <>
              <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl -translate-y-12 translate-x-12"></div>
              <div className="absolute bottom-0 left-0 w-48 h-48 bg-primary-400/20 rounded-full blur-2xl translate-y-12 -translate-x-12"></div>
            </>
          )}
        </div>

        {/* Upgrade Options (for free users) */}
        {!isPremium && (
          <>
            <div className="mb-10">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-cream-100">Unlock Full Potential</h2>
              <p className="text-slate-600 dark:text-cream-500 mt-2">All plans include the same Premium features. Choose your billing cycle:</p>
            </div>

            <div className="grid md:grid-cols-3 gap-8 mb-16">
              {/* Monthly */}
              <div className="group bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] p-8 hover:border-primary-200 hover:shadow-xl hover:shadow-primary-500/5 dark:hover:shadow-terra-500/5 transition-all">
                <h3 className="font-bold text-slate-600 dark:text-cream-500 uppercase tracking-widest text-xs">Premium · Monthly</h3>
                <div className="mt-4 flex items-baseline gap-1">
                  <span className="text-4xl font-black text-slate-900 dark:text-cream-100">$2.49</span>
                  <span className="text-slate-400 dark:text-white/40 font-bold">/mo</span>
                </div>
                <p className="text-sm text-green-600 mt-4 font-bold">7-day free trial included</p>
                <button
                  onClick={() => handleUpgrade('monthly')}
                  className="w-full mt-8 bg-slate-900 dark:bg-cream-100 hover:bg-slate-800 dark:hover:bg-white text-white dark:text-ink py-4 rounded-2xl font-bold transition-all shadow-lg shadow-slate-900/10 dark:shadow-none active:scale-[0.98]"
                >
                  Join Monthly
                </button>
              </div>

              {/* Yearly */}
              <div className="group relative bg-white dark:bg-[#242424] rounded-[2rem] border-2 border-primary-500 dark:border-terra-500 p-8 shadow-2xl shadow-primary-500/10 dark:shadow-terra-500/15 scale-105 z-10">
                <div className="absolute -top-4 left-1/2 -translate-x-1/2 bg-primary-600 dark:bg-terra-500 text-white text-[10px] font-black uppercase tracking-[0.2em] px-5 py-1.5 rounded-full shadow-lg">
                  Most Popular
                </div>
                <h3 className="font-bold text-primary-600 dark:text-terra-400 uppercase tracking-widest text-xs">Premium · Yearly</h3>
                <div className="mt-4 flex items-baseline gap-1">
                  <span className="text-5xl font-black text-slate-900 dark:text-cream-100">$24.99</span>
                  <span className="text-slate-400 dark:text-white/40 font-bold">/yr</span>
                </div>
                <p className="text-sm text-green-600 mt-4 font-bold flex items-center gap-1.5">
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                  </svg>
                  Save $4.89 vs monthly
                </p>
                <button
                  onClick={() => handleUpgrade('yearly')}
                  className="w-full mt-8 bg-primary-600 dark:bg-terra-500 hover:bg-primary-700 dark:hover:bg-terra-600 text-white py-4 rounded-2xl font-bold transition-all shadow-xl shadow-primary-500/25 dark:shadow-terra-500/15 active:scale-[0.98]"
                >
                  Join Yearly
                </button>
              </div>

              {/* Lifetime */}
              <div className="group bg-white dark:bg-[#242424] rounded-3xl border border-slate-200 dark:border-white/[0.06] p-8 hover:border-primary-200 hover:shadow-xl hover:shadow-primary-500/5 dark:hover:shadow-terra-500/5 transition-all">
                <h3 className="font-bold text-slate-600 dark:text-cream-500 uppercase tracking-widest text-xs">Premium · Lifetime</h3>
                <div className="mt-4 flex items-baseline gap-1">
